INSERT INTO public."PRODUCT" ("PRODUCT_ID","PRODUCT_NAME","PRODUCT_DESCRIPTION","PRODUCT_IMAGE","PRODUCT_QUANTITY","PRODUCT_PRICE","CREATED_AT","UPDATED_AT","PRODUCT_CATEGORY","GENDER") VALUES
	 ('75291eeb-0d9f-4173-a431-6d4e7d4a8c0c','LeBron XXII ''Crown Jewel'' EP','{"title": "", "benefits": ["Synthetic leather upper", "Multi-directional traction pattern", "Colour Shown: White/Medium Ash/Hot Lava/Volt Glow", "Style: FZ1095-101", "Country/Region of Origin: China"], "description": "LeBron isn''t slowing down any time soon. The open-court nightmare is as fast and spry as ever. But even Bron needs support when he''s at full throttle. That''s why we levelled up the LeBron 22. Newly implemented saddle wings offer optimal midfoot stability. They complement the heel and forefoot Air Zoom units, so the King can keep pushing the sport forwards. This version is inspired by LeBron''s relationship with his youngest son and the sense of clarity it brings. With its extra-durable rubber outsole, this version gives you traction for outdoor courts.", "current_price": "5,279,000₫5,279,000₫5,279,000₫", "reason_to_buy": "", "product_details": ["Synthetic leather upper", "Multi-directional traction pattern", "Colour Shown: White/Medium Ash/Hot Lava/Volt Glow", "Style: FZ1095-101", "Country/Region of Origin: China"]}','https://static.nike.com/a/images/c_limit,w_592,f_auto/t_product_v1/91a51763-80fe-488e-a5b2-8f9aff4c9794/LEBRON+XXII+EP.png',90,308.74,'2024-12-22 15:23:43.070011','2024-12-22 15:23:43.070011','basketball','men'),
	 ('312b1159-b8ae-4f01-bae1-8f536b1094a5','LeBron XXII ''Currency'' EP','{"title": "", "benefits": ["A breathable dimensional mesh on the upper", "Multi-directional traction pattern", "Colour Shown: White/Green Glow/Pink Foam/Baltic Blue", "Style: FZ1098-100", "Country/Region of Origin: China"], "description": "LeBron isn''t slowing down any time soon. The open-court nightmare is as fast and spry as ever. But even Bron needs support when he''s at full throttle. That''s why we levelled up the LeBron 22. Newly implemented saddle wings offer optimal midfoot stability. They complement the heel and forefoot Air Zoom units, so the King can keep pushing the sport forwards. This version nods to one of LeBron''s favourite board games and his willingness to make deposits in the everyday grind that pays dividends. With its extra-durable rubber outsole, this version gives you traction for outdoor courts.", "current_price": "5,869,000₫5,869,000₫5,869,000₫", "reason_to_buy": "", "product_details": ["A breathable dimensional mesh on the upper", "Multi-directional traction pattern", "Colour Shown: White/Green Glow/Pink Foam/Baltic Blue", "Style: FZ1098-100", "Country/Region of Origin: China"]}','https://static.nike.com/a/images/c_limit,w_592,f_auto/t_product_v1/24a62e35-a0ac-4bdb-b864-1e6ca358bc3b/LEBRON+XXII+QS+EP.png',85,354.05,'2024-12-22 15:23:43.071957','2024-12-22 15:23:43.071957','basketball','men'),
	 ('ed875997-3ea7-4f05-b38a-345bf06d6566','Ja 2 ''Foundation'' EP','{"title": "", "benefits": ["Extra ankle padding gives you comfort when landing and taking off.", "Raised foam collar adds extra cosiness around your Achilles heel.", "Colour Shown: Black/Light Smoke Grey/Light Lemon Twist/Phantom", "Style: FD7327-001", "Country/Region of Origin: China"], "description": "Ja puts in the work to be great so he can be at his best when the game''s on the line. That''s why we gave the Ja 2 a lighter design. It works with Air Zoom cushioning to help keep him fresh when he''s in the lab. And the tractor tyre-inspired traction helps him change direction with ease. Ja''s about that grind. Are you? With its extra-durable rubber outsole, this version gives you traction for outdoor courts.", "current_price": "3,519,000₫3,519,000₫3,519,000₫", "reason_to_buy": "", "product_details": ["Colour Shown: Black/Light Smoke Grey/Light Lemon Twist/Phantom", "Style: FD7327-001", "Country/Region of Origin: China"]}','https://static.nike.com/a/images/c_limit,w_592,f_auto/t_product_v1/641e2959-1529-4157-9801-0e92e043782a/JA+2+EP.png',87,258.33,'2024-12-22 15:23:43.072786','2024-12-22 15:23:43.072786','basketball','men'),
	 ('0b754cc0-0d4a-4381-b8cc-0007bd6fea20','Ja 2 ''Nightmare'' EP','{"title": "", "benefits": ["Extra ankle padding gives you comfort when landing and taking off.", "Raised foam collar adds extra cosiness around your Achilles heel.", "Colour Shown: University Red/Black/Jade Horizon/Celestial Gold", "Style: HQ2637-600", "Country/Region of Origin: China"], "description": "Ja puts in the work to be great so he can be at his best when the game''s on the line. That''s why we gave the Ja 2 a lighter design. It works with Air Zoom cushioning to help keep him fresh when he''s in the lab. And the tractor tyre-inspired traction helps him change direction with ease. Ja''s about that grind. Are you? With its extra-durable rubber outsole, this version gives you traction for outdoor courts. This gory, grimy design pays homage to Ja''s spooky status as an unsolvable mismatch on the floor.", "current_price": "3,829,000₫3,829,000₫3,829,000₫", "reason_to_buy": "", "product_details": ["Colour Shown: University Red/Black/Jade Horizon/Celestial Gold", "Style: HQ2637-600", "Country/Region of Origin: China"]}','https://static.nike.com/a/images/c_limit,w_592,f_auto/t_product_v1/0170bf4f-3211-4860-956e-c0cd974e10a9/JA+2+NIGHTMARE+EP.png',78,493.78,'2024-12-22 15:23:43.07367','2024-12-22 15:23:43.07367','basketball','men'),
	 ('08932286-4fc4-4747-8787-5e89e77142b5','Ja 2 ''Purple Sky'' EP','{"title": "", "benefits": ["Extra ankle padding gives you comfort when landing and taking off.", "Raised foam collar adds extra cosiness around your Achilles heel.", "Not intended for use as personal protective equipment (PPE)", "Colour Shown: Bold Berry/Light Lemon Twist/Dark Raisin/Baltic Blue", "Style: FD7327-500", "Country/Region of Origin: China"], "description": "Ja puts in the work to be great so he can be at his best when the game''s on the line. That''s why we gave the Ja 2 a lighter design. It works with Air Zoom cushioning to help keep him fresh when he''s in the lab. And the tractor tyre-inspired traction helps him change direction with ease. Ja''s about that grind. Are you? With its extra-durable rubber outsole, this version gives you traction for outdoor courts.", "current_price": "3,519,000₫3,519,000₫3,519,000₫", "reason_to_buy": "", "product_details": ["Not intended for use as personal protective equipment (PPE)", "Colour Shown: Bold Berry/Light Lemon Twist/Dark Raisin/Baltic Blue", "Style: FD7327-500", "Country/Region of Origin: China"]}','https://static.nike.com/a/images/c_limit,w_592,f_auto/t_product_v1/20fd0937-0c1e-4149-b098-607ce9c428be/JA+2+EP.png',97,373.56,'2024-12-22 15:23:43.074679','2024-12-22 15:23:43.074679','basketball','men'),
	 ('3bffb7f6-cb57-4814-9edf-68b53405d293','Luka 3 PF','{"title": "", "benefits": ["Pull tab on heel", "The PF edition is designed with a wider fit and optimised for play on outdoor courts.", "Colour Shown: Black/Hyper Jade/Pink Prime/Hyper Grape", "Style: FQ1285-002", "Country/Region of Origin: Vietnam"], "description": "Shift your game into high gear with the lightest Luka yet. Designed to help you create space through acceleration, the Luka 3 features full-length Cushlon 3.0 foam for a smooth heel-to-toe transition. A strong but flexible plate underfoot brings lateral containment, helping you drive out of your step-back to attack the basket. We built speed into the design as well, helping you look 100 as you blow past.", "current_price": "3,829,000₫3,829,000₫3,829,000₫", "reason_to_buy": "", "product_details": ["Pull tab on heel", "The PF edition is designed with a wider fit and optimised for play on outdoor courts.", "Colour Shown: Black/Hyper Jade/Pink Prime/Hyper Grape", "Style: FQ1285-002", "Country/Region of Origin: Vietnam"]}','https://static.nike.com/a/images/c_limit,w_592,f_auto/t_product_v1/u_126ab356-44d8-4a06-89b4-fcdcc8df0245,c_scale,fl_relative,w_1.0,h_1.0,fl_layer_apply/754881e3-8550-4635-ab1a-99f0742be06d/JORDAN+LUKA+3+PF.png',88,391.10,'2024-12-22 15:23:43.075558','2024-12-22 15:23:43.075558','basketball','men'),
	 ('be95b368-b699-406c-b0b5-9cfc656d67b2','Nike G.T. Cut Academy By You','{"title": "", "benefits": null, "description": "", "current_price": "", "reason_to_buy": "", "product_details": null}','https://static.nike.com/a/images/c_limit,w_592,f_auto/t_product_v1/b9eb60e3-b904-4dbe-9eb7-252c91943cae/AIR+ZOOM+G.T.+CUT+ACADEMY+NBY.png',71,215.24,'2024-12-22 15:23:43.179103','2024-12-22 15:23:43.179103','basketball','men'),
	 ('dea14f9a-77ef-4e51-ba87-708ad79fa1ad','Tatum 3 PF ''Zen''','{"title": "", "benefits": ["PF edition is designed to fit wide for play on outdoor courts.", "Colour Shown: Platinum Tint/Particle Grey/Grey Fog/Black", "Style: FZ6601-001", "Country/Region of Origin: Vietnam"], "description": "Calm under pressure. That''s Jayson in a nutshell. Sure, he hears the back and forth, but he doesn''t let the pressure get to him. This Tatum 3 is all about that balance. Soothing shades of grey mix with just the right amount of energising colour. Plus, a contouring fit and court-ready tech like Cushlon 3.0 foam support you throughout the game.", "current_price": "3,669,000₫3,669,000₫3,669,000₫", "reason_to_buy": "", "product_details": ["PF edition is designed to fit wide for play on outdoor courts.", "Colour Shown: Platinum Tint/Particle Grey/Grey Fog/Black", "Style: FZ6601-001", "Country/Region of Origin: Vietnam"]}','https://static.nike.com/a/images/c_limit,w_592,f_auto/t_product_v1/u_126ab356-44d8-4a06-89b4-fcdcc8df0245,c_scale,fl_relative,w_1.0,h_1.0,fl_layer_apply/4aa50aaf-1393-4c1d-8eb3-db2a1fb16714/JORDAN+TATUM+3+PF.png',67,239.09,'2024-12-22 15:23:43.076355','2024-12-22 15:23:43.076355','basketball','men'),
	 ('4f3e3fcb-c9e3-4c1f-acdd-ab4c2e174746','Tatum 3 PF ''Zero Days Off''','{"title": "", "benefits": ["PF edition is designed to fit wide for play on outdoor courts.", "Colour Shown: Seafoam/Spruce Aura/Arctic Orange/Apricot Agate", "Style: FZ6601-002", "Country/Region of Origin: Vietnam"], "description": "When it comes to putting in the work, Jayson''s entirely self-motivated—and he doesn''t believe in taking a day off. As his expectations are so high, he feels zero pressure from the outside world. We''re honouring that tireless pursuit of greatness with this Tatum 3. Lightweight and packed with court-ready tech like responsive Cushlon foam and a contouring fit, it helps support you in your push to be the best. Can you commit to zero days off?", "current_price": "3,669,000₫3,669,000₫3,669,000₫", "reason_to_buy": "", "product_details": ["PF edition is designed to fit wide for play on outdoor courts.", "Colour Shown: Seafoam/Spruce Aura/Arctic Orange/Apricot Agate", "Style: FZ6601-002", "Country/Region of Origin: Vietnam"]}','https://static.nike.com/a/images/c_limit,w_592,f_auto/t_product_v1/u_126ab356-44d8-4a06-89b4-fcdcc8df0245,c_scale,fl_relative,w_1.0,h_1.0,fl_layer_apply/03240aad-2e7f-43df-b129-65fefe67e8a6/JORDAN+TATUM+3+PF.png',88,301.25,'2024-12-22 15:23:43.077186','2024-12-22 15:23:43.077186','basketball','men'),
	 ('d1a2d556-ec19-4769-8893-5bb8b59a988a','G.T. Hustle Academy EP','{"title": "", "benefits": ["Colour Shown: College Navy/Psychic Blue/Racer Blue/White", "Style: FJ7808-401", "Country/Region of Origin: Vietnam"], "description": "The G.T. Hustle Academy helps keep you fast, wherever your next game is. A full Flyknit upper works with responsive foams to help you feel fresh on the court. With its extra-durable rubber outsole, this version gives you traction for outdoor courts.", "current_price": "2,649,000₫2,649,000₫2,649,000₫", "reason_to_buy": "", "product_details": ["Colour Shown: College Navy/Psychic Blue/Racer Blue/White", "Style: FJ7808-401", "Country/Region of Origin: Vietnam"]}','https://static.nike.com/a/images/c_limit,w_592,f_auto/t_product_v1/8891df66-d876-4c0f-9426-54d6216a9045/G.T.+HUSTLE+ACADEMY+EP.png',84,400.82,'2024-12-22 15:23:43.077899','2024-12-22 15:23:43.077899','basketball','men');
