	 ('e4974108-181e-4efa-b782-1d333d5419ca','Nike G.T. Cut Academy By You','{"title": "", "benefits": null, "description": "", "current_price": "", "reason_to_buy": "", "product_details": null}','https://static.nike.com/a/images/c_limit,w_592,f_auto/t_product_v1/68c764fc-6bbc-43eb-a925-a956cb933fb2/AIR+ZOOM+G.T.+CUT+ACADEMY+NBY.png',99,226.85,'2024-12-22 15:23:43.165415','2024-12-22 15:23:43.165415','basketball','men'),
	 ('1dc1a3ce-a020-4754-9449-10d9453b7abe','Sabrina 2 By You','{"title": "", "benefits": null, "description": "", "current_price": "", "reason_to_buy": "", "product_details": null}','https://static.nike.com/a/images/c_limit,w_592,f_auto/t_product_v1/ba3749ef-1f98-418d-a31d-9fe4e44e892d/SABRINA+2+NBY.png',65,338.33,'2024-12-22 15:23:43.184881','2024-12-22 15:23:43.184881','basketball','men'),
	 ('273d68f5-6171-475e-837f-dcedcdb0b4f0','Jordan One Take 5 PF','{"title": "", "benefits": ["PF edition is designed to fit wide for play on outdoor courts.", "Embroidered tongue logo", "Jumpman on the midsole", "Colour Shown: Black/Anthracite/Sail/Taxi", "Style: FD2336-007", "Country/Region of Origin: Vietnam"], "description": "Accelerate, bank, shoot, score—then repeat. Russell Westbrook''s latest shoe is here to assist your speed game so you can stay unstoppable on the break. The lateral eyestay and wraparound toe piece help you feel contained on the court. Underfoot, you get energy-returning Zoom Air cushioning in the forefoot so you can keep sinkin'' ''em from the first to the fourth.", "current_price": "2,929,000₫2,929,000₫2,929,000₫", "reason_to_buy": "", "product_details": ["PF edition is designed to fit wide for play on outdoor courts.", "Embroidered tongue logo", "Jumpman on the midsole", "Colour Shown: Black/Anthracite/Sail/Taxi", "Style: FD2336-007", "Country/Region of Origin: Vietnam"]}','https://static.nike.com/a/images/c_limit,w_592,f_auto/t_product_v1/u_126ab356-44d8-4a06-89b4-fcdcc8df0245,c_scale,fl_relative,w_1.0,h_1.0,fl_layer_apply/40ed29c0-da68-4c05-abaa-4acdebdf4a12/JORDAN+ONE+TAKE+5+PF.png',70,224.22,'2024-12-22 15:23:43.131254','2024-12-22 15:23:43.131254','basketball','men'),
	 ('80101da3-3c93-4fa6-ac70-e0639f25f5ce','Nike Impact 4','{"title": "", "benefits": ["Forefoot underlay add stability.", "Mesh is lightweight and semi-transparent.", "Colour Shown: White/Pure Platinum/Black", "Style: DM1124-100", "Country/Region of Origin: India"], "description": "Elevate your game and your hops. Charged with Max Air cushioning in the heel, this lightweight, secure shoe helps you get off the ground confidently and land comfortably. Plus, rubber wraps up the sides for added durability and stability.", "current_price": "2,649,000₫2,649,000₫2,649,000₫", "reason_to_buy": "", "product_details": ["Colour Shown: White/Pure Platinum/Black", "Style: DM1124-100", "Country/Region of Origin: India"]}','https://static.nike.com/a/images/c_limit,w_592,f_auto/t_product_v1/5eb3d983-e731-4a7a-8990-446d231c2229/NIKE+AIR+MAX+IMPACT+4.png',67,421.66,'2024-12-22 15:23:43.131991','2024-12-22 15:23:43.131991','basketball','men'),
	 ('f2205ee1-877c-4728-8c2c-8aa73f4e1048','LeBron NXXT Gen AMPD EP','{"title": "", "benefits": ["Colour Shown: Black/University Red/Metallic Gold", "Style: FJ1567-001", "Country/Region of Origin: Vietnam"], "description": "Whether you''re a dunk-competition-like leaper or a below-the-rim wonder roaming the baseline, feel fast, low to the court and assured in the LeBron NXXT Gen. We tailored specifically it to meet the demands of today''s fast-paced game so that you can stay ahead of the opposition with your speed in all directions. With its extra-durable rubber outsole, this version gives you traction for outdoor courts.", "current_price": "4,699,000₫4,699,000₫4,699,000₫", "reason_to_buy": "", "product_details": ["Colour Shown: Black/University Red/Metallic Gold", "Style: FJ1567-001", "Country/Region of Origin: Vietnam"]}','https://static.nike.com/a/images/c_limit,w_592,f_auto/t_product_v1/0a1ad373-cfe3-4569-a730-16eb9e1783ae/ZM+LEBRON+NXXT+GEN+AMPD+EP.png',88,313.32,'2024-12-22 15:23:43.132715','2024-12-22 15:23:43.132715','basketball','men');
