	 ('ba7459fa-792b-4de6-ae13-9b33b58c98f3','Nike G.T. Cut Academy By You','{"title": "", "benefits": null, "description": "", "current_price": "", "reason_to_buy": "", "product_details": null}','https://static.nike.com/a/images/c_limit,w_592,f_auto/t_product_v1/f1ef3d02-2a0b-44ea-aa9f-84cbc4a9a060/AIR+ZOOM+G.T.+CUT+ACADEMY+NBY.png',82,366.65,'2024-12-22 15:23:43.187715','2024-12-22 15:23:43.187715','basketball','men');
