	 ('c13e743c-e4a9-4fae-888a-ab09a1cbbcae','Sabrina 2 By Sabrina','{"title": "", "benefits": null, "description": "", "current_price": "", "reason_to_buy": "", "product_details": null}','https://static.nike.com/a/images/c_limit,w_592,f_auto/t_product_v1/1b739964-dd95-4060-bafe-2f7999ece971/SABRINA+2+NBY.png',98,217.46,'2024-12-22 15:29:13.118939','2024-12-22 15:29:13.118939','basketball','women'),
	 ('f9b63a74-8794-4d3f-a3b4-b7da9c7ffb6e','Cosmic Unity 3','{"title": "", "benefits": ["Colour Shown: Barely Volt/Coconut Milk/Alchemy Pink/Anthracite", "Style: DV2757-700", "Country/Region of Origin: Vietnam"], "description": "Better for your game, designed with sustainability in mind—two things you care about—the Cosmic Unity 3 has a secure, lightweight design for a low-to-the-ground feel. It gives you cloud-like cushioning for explosive speed and quick changes of direction, the difference-makers in a game that''s becoming more extraterrestrial.", "current_price": "2,645,399₫2,645,399₫2,645,399₫", "reason_to_buy": "", "product_details": ["Colour Shown: Barely Volt/Coconut Milk/Alchemy Pink/Anthracite", "Style: DV2757-700", "Country/Region of Origin: Vietnam"]}','https://static.nike.com/a/images/c_limit,w_592,f_auto/t_product_v1/2334482a-9a02-4bc0-9951-d0d09dced968/COSMIC+UNITY+3.png',55,451.43,'2024-12-22 15:23:43.314555','2024-12-22 15:23:43.314555','basketball','men'),
	 ('f20543a5-cebb-4d68-a5df-dab5be3aed22','Cosmic Unity 3','{"title": "", "benefits": ["Colour Shown: Football Grey/Ashen Slate/Light Carbon/White", "Style: DV2757-006", "Country/Region of Origin: Vietnam"], "description": "Better for your game, designed with sustainability in mind—two things you care about—the Cosmic Unity 3 has a secure, lightweight design for a low-to-the-ground feel. It gives you cloud-like cushioning for explosive speed and quick changes of direction, the difference-makers in a game that''s becoming more extraterrestrial.", "current_price": "2,865,849₫2,865,849₫2,865,849₫", "reason_to_buy": "", "product_details": ["Colour Shown: Football Grey/Ashen Slate/Light Carbon/White", "Style: DV2757-006", "Country/Region of Origin: Vietnam"]}','https://static.nike.com/a/images/c_limit,w_592,f_auto/t_product_v1/2f98689d-ddf7-4c59-9986-93c39849f571/COSMIC+UNITY+3.png',58,381.58,'2024-12-22 15:23:43.315338','2024-12-22 15:23:43.315338','basketball','men'),
	 ('438d5e10-2827-4f77-853d-801e1b7ca70e','Zion 3 M.U.D. ''Ash'' SE PF','{"title": "", "benefits": ["The PF edition is designed with a wider fit and optimised for play on outdoor courts.", "Colour Shown: Black/Sail/Dark Ash", "Style: FN1778-002", "Country/Region of Origin: Vietnam"], "description": "Sophistication on foot, domination on the court: this Zion 3 is M.U.D. (Made Uniquely Different). Nubuck leather and suede give you a luxe look while the special-edition forefoot strap lets you customise your containment. Full-length Air Zoom further sets this pair apart. Go ahead, rise from the ashes and let ''em see how strong your game is.", "current_price": "3,527,199₫3,527,199₫3,527,199₫", "reason_to_buy": "", "product_details": ["The PF edition is designed with a wider fit and optimised for play on outdoor courts.", "Colour Shown: Black/Sail/Dark Ash", "Style: FN1778-002", "Country/Region of Origin: Vietnam"]}','https://static.nike.com/a/images/c_limit,w_592,f_auto/t_product_v1/u_126ab356-44d8-4a06-89b4-fcdcc8df0245,c_scale,fl_relative,w_1.0,h_1.0,fl_layer_apply/8757bda7-3ab6-44ae-8645-974099dcf963/JORDAN+ZION+3+SE+PF.png',94,459.93,'2024-12-22 15:23:43.316172','2024-12-22 15:23:43.316172','basketball','men'),
	 ('8c0a6be1-f31a-4b3c-bc27-500a723a117d','Zion 3 M.U.D. "Light Bone" PF','{"title": "", "benefits": ["PF edition is designed to fit wide for play on outdoor courts.", "Colour Shown: Light Bone/Sail/Volt/Light Bone", "Style: FN1778-040", "Country/Region of Origin: Vietnam"], "description": "Sophistication on foot, domination on the court: this Zion III is M.U.D. (Made Uniquely Different). The nubuck leather and suede give you a luxe look. The special-edition forefoot strap lets you customise your containment, while full-length Zoom Air further sets this pair apart. The tonal mud-splatter embroidery adds grit to the super-clean Light Bone upper—a reminder of what it takes to achieve greatness.", "current_price": "2,645,399₫2,645,399₫2,645,399₫", "reason_to_buy": "", "product_details": ["PF edition is designed to fit wide for play on outdoor courts.", "Colour Shown: Light Bone/Sail/Volt/Light Bone", "Style: FN1778-040", "Country/Region of Origin: Vietnam"]}','https://static.nike.com/a/images/c_limit,w_592,f_auto/t_product_v1/u_126ab356-44d8-4a06-89b4-fcdcc8df0245,c_scale,fl_relative,w_1.0,h_1.0,fl_layer_apply/56a05251-b96e-4e2f-97cf-e77c33ddef4c/JORDAN+ZION+3+SE+PF.png',58,401.37,'2024-12-22 15:23:43.316994','2024-12-22 15:23:43.316994','basketball','men'),
	 ('bfc0b643-eb7d-446d-b5d7-de458db28b12','Zion 3 ''Orchid'' SE PF','{"title": "", "benefits": ["The PF edition is designed with a wider fit and optimised for play on outdoor courts.", "Colour Shown: Plum Fog/Sail/Black", "Style: FN1778-500", "Country/Region of Origin: Vietnam"], "description": "Sophistication on foot, domination on the court: this Zion 3 is M.U.D. (Made Uniquely Different). The nubuck leather and suede give you a luxe look. The special-edition forefoot strap lets you customise your containment, while full-length Zoom Air further sets this pair apart. The tonal mud-splatter embroidery adds grit to the super-clean light purple upper—a reminder of what it takes to achieve greatness.", "current_price": "3,527,199₫3,527,199₫3,527,199₫", "reason_to_buy": "", "product_details": ["The PF edition is designed with a wider fit and optimised for play on outdoor courts.", "Colour Shown: Plum Fog/Sail/Black", "Style: FN1778-500", "Country/Region of Origin: Vietnam"]}','https://static.nike.com/a/images/c_limit,w_592,f_auto/t_product_v1/u_126ab356-44d8-4a06-89b4-fcdcc8df0245,c_scale,fl_relative,w_1.0,h_1.0,fl_layer_apply/18364584-e9cf-4d45-8b9c-b2349ca96401/JORDAN+ZION+3+SE+PF.png',96,453.30,'2024-12-22 15:23:43.31771','2024-12-22 15:23:43.31771','basketball','men'),
	 ('a285b84a-a58c-45a1-83d1-7790b1e35201','Zion 3 ''Z-3D'' PF','{"title": "", "benefits": ["PF edition is designed to fit wide for play on outdoor courts.", "Colour Shown: Football Grey/Flash Crimson/Chlorine Blue/Black", "Style: FZ1319-060", "Country/Region of Origin: Vietnam"], "description": "Zion''s got a thing for nostalgia, and the Z-3D brings that love to life. The shoe itself is designed with court-ready tech designed to help you stay low, stay contained and explode skywards with a cushioned return to earth.", "current_price": "2,865,849₫2,865,849₫2,865,849₫", "reason_to_buy": "", "product_details": ["PF edition is designed to fit wide for play on outdoor courts.", "Colour Shown: Football Grey/Flash Crimson/Chlorine Blue/Black", "Style: FZ1319-060", "Country/Region of Origin: Vietnam"]}','https://static.nike.com/a/images/c_limit,w_592,f_auto/t_product_v1/u_126ab356-44d8-4a06-89b4-fcdcc8df0245,c_scale,fl_relative,w_1.0,h_1.0,fl_layer_apply/519973a6-a890-4e1e-b46a-d5b3ce2db905/JORDAN+ZION+3+NRG+PF.png',57,203.35,'2024-12-22 15:23:43.318387','2024-12-22 15:23:43.318387','basketball','men'),
	 ('348136b0-b00c-4620-b5ee-dcd1bdf5470d','Nike Phantom GX 2 Academy EasyOn Electric','{"title": "", "benefits": ["For use on natural and synthetic surfaces", "Cushioned Insole", "Colour Shown: Multi-Colour/Multi-Colour", "Style: FN8199-900", "Country/Region of Origin: Indonesia"], "description": "Looking to take your game to the next level? The Phantom GX 2 Academy helps put you in prime position of the goal, whether you''re the playmaker, assister or finisher. The rest is up to you. Created with goals in mind, NikeSkin covers the striking area of the boot, while quick traction helps guide your unscripted agility.", "current_price": "2,929,000₫2,929,000₫2,929,000₫", "reason_to_buy": "", "product_details": ["For use on natural and synthetic surfaces", "Cushioned Insole", "Colour Shown: Multi-Colour/Multi-Colour", "Style: FN8199-900", "Country/Region of Origin: Indonesia"]}','https://static.nike.com/a/images/c_limit,w_592,f_auto/t_product_v1/cb278f08-a4ad-43b8-824a-641196ddaf4c/PHANTOM+GX+II+ACAD+EASE+FGMG.png',56,325.09,'2024-12-22 15:24:19.621347','2024-12-22 15:24:19.621347','football','men'),
	 ('4b51856f-e84f-4d0a-b125-f67e0be7f116','Nike G.T. Hustle 2 EP','{"title": "", "benefits": ["Foam tongue helps reduce lace pressure.", "The Waffle herringbone traction pattern offers great bite and court feel.", "Colour Shown: White/Malachite/Pure Platinum/Vintage Green", "Style: DJ9404-103", "Country/Region of Origin: China"], "description": "One step can make all the difference when it''s game point, like a sneaky successful back-door layup that''s blocked if not for a sliver of separation, or a last-second leap at your opponent that sends their 3 clanking off the rim. We used insights from female athletes to make the G.T. Hustle 2 soft, supportive and lightweight—which every basketball player needs. Loaded with cushioning in the core and Zoom Air, this shoe helps you stay moving forwards—from check-up to \"that''s game\". Sprint, stop and score from end to end, focusing on dominating, not deteriorating, down the stretch. With its extra-durable rubber outsole, this version gives you traction for outdoor courts.", "current_price": "3,249,349₫3,249,349₫3,249,349₫", "reason_to_buy": "", "product_details": ["Colour Shown: White/Malachite/Pure Platinum/Vintage Green", "Style: DJ9404-103", "Country/Region of Origin: China"]}','https://static.nike.com/a/images/c_limit,w_592,f_auto/t_product_v1/a8108cf1-7c04-466f-a1e1-6c63dd5511ae/AIR+ZOOM+G.T.+HUSTLE+2+EP.png',75,486.22,'2024-12-22 15:23:43.319035','2024-12-22 15:23:43.319035','basketball','men'),
	 ('6c36a78d-2e57-4de5-9c7a-a5329ee8d2f9','Nike Tiempo Legend 10 Club','{"title": "", "benefits": ["For use on natural and synthetic surfaces", "Cushioned insole", "Colour Shown: Black/Deep Jungle/Black", "Style: DV4344-002", "Country/Region of Origin: Vietnam"], "description": "Even Legends find ways to evolve. Whether you''re starting out or just playing for fun, the latest iteration of this Club boot gets you on the pitch without compromising on quality. The synthetic leather contours to your foot and doesn''t overstretch, giving you better control. Lighter and sleeker than any other Tiempo to date, the Legend 10 is for any position on the pitch, whether you''re sending a pinpoint pass through the defence or tracking back to stop a break-away.", "current_price": "1,609,000₫1,609,000₫1,609,000₫", "reason_to_buy": "", "product_details": ["For use on natural and synthetic surfaces", "Cushioned insole", "Colour Shown: Black/Deep Jungle/Black", "Style: DV4344-002", "Country/Region of Origin: Vietnam"]}','https://static.nike.com/a/images/c_limit,w_592,f_auto/t_product_v1/ec2b2eb3-a34f-4411-a6d9-fc218ef848ef/LEGEND+10+CLUB+FG%2FMG.png',60,319.82,'2024-12-22 15:24:19.61641','2024-12-22 15:24:19.61641','football','men');
INSERT INTO public."PRODUCT" ("PRODUCT_ID","PRODUCT_NAME","PRODUCT_DESCRIPTION","PRODUCT_IMAGE","PRODUCT_QUANTITY","PRODUCT_PRICE","CREATED_AT","UPDATED_AT","PRODUCT_CATEGORY","GENDER") VALUES
	 ('8c9cb4d9-70e5-4454-b75a-9d306f7ec392','Nike Mercurial Superfly 9 Elite','{"title": "", "benefits": ["For use on slightly wet, short-grass pitches", "Not intended for use as personal protective equipment (PPE)", "Cushioned insole", "Colour Shown: Atmosphere Grey/Black", "Style: FN5613-001", "Country/Region of Origin: China"], "description": "We make Elite football boots for those obsessed with the game, the hidden gems that grind in the shadows, behind the scenes, when nobody else is watching. This special edition Superfly 9 is no exception. Featuring a metallic Swoosh design, they will be on the feet of the best players as they take to the pitch of the world''s biggest tournaments. Add in a specially designed Air Zoom unit for speed and you have a championship-level boot ready for personal brilliance.", "current_price": "8,349,000₫8,349,000₫8,349,000₫", "reason_to_buy": "", "product_details": ["For use on slightly wet, short-grass pitches", "Not intended for use as personal protective equipment (PPE)", "Cushioned insole", "Colour Shown: Atmosphere Grey/Black", "Style: FN5613-001", "Country/Region of Origin: China"]}','https://static.nike.com/a/images/c_limit,w_592,f_auto/t_product_v1/25cc3c76-9257-48f7-9908-2a9443c49e88/ZOOM+SUPERFLY+9+ELITE+FG+AS.png',78,356.47,'2024-12-22 15:24:19.617664','2024-12-22 15:24:19.617664','football','men'),
	 ('306393dd-febe-4b95-9412-9540fab59f14','Nike Mercurial Vapor 16 Club','{"title": "", "benefits": ["For use on natural and synthetic surfaces", "Cushioned insole", "Colour Shown: Glacier Blue/Blue Orbit", "Style: FQ8441-400", "Country/Region of Origin: Vietnam"], "description": "Whether you''re starting out or just playing for fun, the Club boot gets you on the pitch without compromising on quality. The Vapor 16 is made with speed in mind. Mix that velocity with touch and comfort? It’s goal time.", "current_price": "1,609,000₫1,609,000₫1,609,000₫", "reason_to_buy": "", "product_details": ["For use on natural and synthetic surfaces", "Cushioned insole", "Colour Shown: Glacier Blue/Blue Orbit", "Style: FQ8441-400", "Country/Region of Origin: Vietnam"]}','https://static.nike.com/a/images/c_limit,w_592,f_auto/t_product_v1/05442d82-fde1-401f-a24e-33409f65c375/VAPOR+16+CLUB+FG%2FMG.png',72,356.53,'2024-12-22 15:24:19.618463','2024-12-22 15:24:19.618463','football','men'),
	 ('7144cfc2-087b-45ad-9056-a4e7c4695c70','Nike Mercurial Superfly 10 Academy','{"title": "", "benefits": ["For use on natural and synthetic surfaces", "Cushioned insole", "Colour Shown: Black/Deep Jungle/Black", "Style: FQ1456-002", "Country/Region of Origin: Indonesia"], "description": "Looking to take your speed to the next level? We made these Academy boots with an improved heel Air Zoom unit. It gives you the propulsive feel needed to break through the back line. The result is the most responsive Mercurial we''ve ever made, so you can dictate pace and tempo all match long.", "current_price": "2,779,000₫2,779,000₫2,779,000₫", "reason_to_buy": "", "product_details": ["For use on natural and synthetic surfaces", "Cushioned insole", "Colour Shown: Black/Deep Jungle/Black", "Style: FQ1456-002", "Country/Region of Origin: Indonesia"]}','https://static.nike.com/a/images/c_limit,w_592,f_auto/t_product_v1/615bd8bf-ea41-487a-b3e1-70399eef6be6/ZM+SUPERFLY+10+ACAD+FG%2FMG.png',82,411.49,'2024-12-22 15:24:19.619572','2024-12-22 15:24:19.619572','football','men'),
	 ('f0346128-b556-4bc9-8209-c9754cea26f4','Nike Mercurial Superfly 10 Club','{"title": "", "benefits": ["For use on natural and synthetic surfaces", "Cushioned insole", "Colour Shown: Glacier Blue/Blue Orbit", "Style: FQ8314-400", "Country/Region of Origin: Vietnam"], "description": "Whether you''re starting out or just playing for fun, the Club boot gets you on the pitch without compromising on quality. The Superfly 10 is made with speed in mind. Mix that velocity with touch and comfort? It’s goal time.", "current_price": "1,889,000₫1,889,000₫1,889,000₫", "reason_to_buy": "", "product_details": ["For use on natural and synthetic surfaces", "Cushioned insole", "Colour Shown: Glacier Blue/Blue Orbit", "Style: FQ8314-400", "Country/Region of Origin: Vietnam"]}','https://static.nike.com/a/images/c_limit,w_592,f_auto/t_product_v1/82182873-0ecc-4b73-898b-62c1d745e95e/SUPERFLY+10+CLUB+FG%2FMG.png',98,295.70,'2024-12-22 15:24:19.620497','2024-12-22 15:24:19.620497','football','men'),
	 ('12291856-a441-4d0d-b341-f28ed0a421ab','Nike G.T. Cut Academy By You','{"title": "", "benefits": null, "description": "", "current_price": "", "reason_to_buy": "", "product_details": null}','https://static.nike.com/a/images/c_limit,w_592,f_auto/t_product_v1/32ddd7b0-0af5-45f1-bb79-fee7e98924cd/AIR+ZOOM+G.T.+CUT+ACADEMY+NBY.png',89,231.98,'2024-12-22 15:29:13.119612','2024-12-22 15:29:13.119612','basketball','women'),
	 ('bed16f1e-0085-4076-aad8-87b3cb9c1742','Sabrina 2 By You','{"title": "", "benefits": null, "description": "", "current_price": "", "reason_to_buy": "", "product_details": null}','https://static.nike.com/a/images/c_limit,w_592,f_auto/t_product_v1/e18c7dbc-8775-44c9-98a6-973898d9f8c3/SABRINA+2+NBY.png',92,244.41,'2024-12-22 15:29:13.120389','2024-12-22 15:29:13.120389','basketball','women'),
	 ('e58de05a-804c-4b7f-8ae8-7674e42a823a','Nike Tiempo Legend 10 Elite','{"title": "", "benefits": ["For use on slightly wet, short-grass pitches", "Cushioned insole", "Colour Shown: Black/Deep Jungle/Black", "Style: DV4328-002", "Country/Region of Origin: Vietnam"], "description": "Even Legends find ways to evolve. The latest iteration of this Elite boot has all-new FlyTouch Plus engineered leather. Softer than natural leather, it contours to your foot and works with All Conditions Control (a grippy texture even in wet weather) so you can dictate the pace of your game. Lighter and sleeker than any other Tiempo to date, the Legend 10 is for any position on the pitch, whether you''re sending a pinpoint pass through the defence or tracking back to stop a break-away.", "current_price": "6,739,000₫6,739,000₫6,739,000₫", "reason_to_buy": "", "product_details": ["For use on slightly wet, short-grass pitches", "Cushioned insole", "Colour Shown: Black/Deep Jungle/Black", "Style: DV4328-002", "Country/Region of Origin: Vietnam"]}','https://static.nike.com/a/images/c_limit,w_592,f_auto/t_product_v1/a1a9a3a2-deac-4569-acd4-f3ae09b572df/LEGEND+10+ELITE+FG.png',59,405.41,'2024-12-22 15:24:19.622231','2024-12-22 15:24:19.622231','football','men'),
	 ('7c75105c-86dd-4c04-a00f-c246dc8451dc','Nike Mercurial Superfly 10 Elite','{"title": "", "benefits": ["For use on slightly wet, short-grass pitches", "Cushioned insole", "Colour Shown: Glacier Blue/Blue Orbit", "Style: FQ1454-400", "Country/Region of Origin: China"], "description": "Obsessed with speed? So are the game''s biggest stars. That''s why we made this Elite boot with an improved 3/4-length Air Zoom unit. It gives you and the sport''s fastest players the propulsive feel needed to break through the back line. The result is the most responsive Mercurial we''ve ever made, because you demand greatness from yourself and your footwear.", "current_price": "8,059,000₫8,059,000₫8,059,000₫", "reason_to_buy": "", "product_details": ["For use on slightly wet, short-grass pitches", "Cushioned insole", "Colour Shown: Glacier Blue/Blue Orbit", "Style: FQ1454-400", "Country/Region of Origin: China"]}','https://static.nike.com/a/images/c_limit,w_592,f_auto/t_product_v1/f71f58eb-ad7b-4495-acd0-163411f79298/ZM+SUPERFLY+10+ELITE+FG.png',51,343.58,'2024-12-22 15:24:19.624062','2024-12-22 15:24:19.624062','football','men'),
	 ('a79c06bd-39b0-4425-8fc4-cb4496d3baae','Nike Phantom GX 2 Club','{"title": "", "benefits": ["For use on natural and synthetic surfaces", "Cushioned insole", "Colour Shown: Blue Fury/White", "Style: FJ2557-400", "Country/Region of Origin: Vietnam"], "description": "Whether you''re starting out or just playing for fun, the Club boot gets you on the pitch without compromising on quality. Created with goals in mind, the Phantom GX 2 Club has a grippy texture covering the striking area of the boot and reliable traction to help guide your unscripted agility.", "current_price": "1,759,000₫1,759,000₫1,759,000₫", "reason_to_buy": "", "product_details": ["For use on natural and synthetic surfaces", "Cushioned insole", "Colour Shown: Blue Fury/White", "Style: FJ2557-400", "Country/Region of Origin: Vietnam"]}','https://static.nike.com/a/images/c_limit,w_592,f_auto/t_product_v1/a3ab8d17-8664-453b-8cfa-afa178155587/PHANTOM+GX+II+CLUB+FG%2FMG.png',70,445.68,'2024-12-22 15:24:19.625163','2024-12-22 15:24:19.625163','football','men'),
	 ('a46de916-5894-49f4-a360-95b7b7a3ba75','Nike Phantom GX 2 Academy','{"title": "", "benefits": ["For use on shorter, synthetic surfaces", "Cushioned insole", "Colour Shown: Black/Deep Jungle/Black", "Style: FJ2577-002", "Country/Region of Origin: Indonesia"], "description": "Looking to take your game to the next level? The Phantom GX 2 Academy helps put you in prime position of the goal, whether you''re the playmaker, assister or finisher. The rest is up to you. Created with goals in mind, NikeSkin covers the striking area of the shoe, while Nike Cyclone 360 traction helps guide your unscripted agility.", "current_price": "2,479,000₫2,479,000₫2,479,000₫", "reason_to_buy": "", "product_details": ["For use on shorter, synthetic surfaces", "Cushioned insole", "Colour Shown: Black/Deep Jungle/Black", "Style: FJ2577-002", "Country/Region of Origin: Indonesia"]}','https://static.nike.com/a/images/c_limit,w_592,f_auto/t_product_v1/62e3d9c1-0d94-4f95-b948-854d25549650/PHANTOM+GX+II+ACADEMY+TF.png',61,428.85,'2024-12-22 15:24:19.626343','2024-12-22 15:24:19.626343','football','men');
