	 ('88ceee6d-3ec6-450b-8901-50a7dbf71c92','Nike InfinityRN 4 By You','{"title": "", "benefits": null, "description": "", "current_price": "", "reason_to_buy": "", "product_details": null}','https://static.nike.com/a/images/c_limit,w_592,f_auto/t_product_v1/e74bd16f-c3ae-4a1c-9343-4c32a83ef993/NIKE+REACTX+INFINITY+RUN+4+NBY.png',83,233.34,'2024-12-22 15:28:42.015813','2024-12-22 15:28:42.015813','running','men'),
	 ('6627dfb3-2402-41c2-836f-6609a38d709e','Nike InfinityRN 4 By You','{"title": "", "benefits": null, "description": "", "current_price": "", "reason_to_buy": "", "product_details": null}','https://static.nike.com/a/images/c_limit,w_592,f_auto/t_product_v1/f61b3d97-8846-45cf-9946-6a46cefcb36d/NIKE+REACTX+INFINITY+RUN+4+NBY.png',72,281.82,'2024-12-22 15:28:42.016446','2024-12-22 15:28:42.016446','running','men'),
	 ('61932e49-acc7-4475-991a-2c5882f4ba60','Nike Pegasus Trail 5 By You','{"title": "", "benefits": null, "description": "", "current_price": "", "reason_to_buy": "", "product_details": null}','https://static.nike.com/a/images/c_limit,w_592,f_auto/t_product_v1/52c2c085-a58f-4542-98c6-31d13625c0af/W+PEGASUS+TRAIL+5+WIDE+NBY.png',59,309.81,'2024-12-22 15:28:42.017096','2024-12-22 15:28:42.017096','running','men'),
	 ('967689d1-c287-4d76-86f5-6cf5cdbbf8f2','Nike Free RN By You','{"title": "", "benefits": null, "description": "", "current_price": "", "reason_to_buy": "", "product_details": null}','https://static.nike.com/a/images/c_limit,w_592,f_auto/t_product_v1/a6c1679f-9a8f-4036-b934-e5163da3f89b/NIKE+FREE+RN+FK+NN+NBY.png',75,298.15,'2024-12-22 15:28:42.017812','2024-12-22 15:28:42.017812','running','men'),
