INSERT INTO public."PRODUCT" ("PRODUCT_ID","PRODUCT_NAME","PRODUCT_DESCRIPTION","PRODUCT_IMAGE","PRODUCT_QUANTITY","PRODUCT_PRICE","CREATED_AT","UPDATED_AT","PRODUCT_CATEGORY","GENDER") VALUES
	 ('f3e021ad-42a4-4ae8-85d6-84b3640d47a3','Nike Structure 25','{"title": "", "benefits": ["The breathable engineered mesh upper has targeted zones for support", "A Cushlon 3.0 foam midsole with a Zoom Air unit in the forefoot for cushioning and stability", "A durable Waffle outsole for grip and stability", "A midfoot support system for enhanced arch support to control pronation", "What''s new? The new Cushlon 3.0 foam underfoot and a higher stack height make it our most stable and supportive model yet.", "Weight: Approx. 289g (men''s size 9)", "Heel-to-toe drop: 10mm", "MR-10 Last—Our best, most consistent fit", "Not intended for use as personal protective equipment (PPE)", "We softened the materials on the inside of the heel, collar and tongue, so that any part of the shoe that''s touching your ankle feels smooth and comfortable.", "Single-layer mesh provides breathability and durability.", "The durable rubber sole has grooves in the forefoot to create flexibility, and vertical grooves down the side help create stability.", "Cinched-down laces", "Moulded heel", "Weight: 322g (men''s size 9)", "Heel-to-toe drop: 10mm", "Not intended for use as personal protective equipment (PPE)", "Colour Shown: Black/Iron Grey/White", "Style: DZ3488-002", "Country/Region of Origin: Vietnam"], "description": "The supportive cushioning provides steadiness for everyday runs. Experience a stable platform without sacrificing performance with a combination of Cushlon 3.0 foam and a Zoom Air unit. Plus, a higher stack height makes it more comfortable, stable and supportive than ever.", "current_price": "3,829,000₫3,829,000₫3,829,000₫", "reason_to_buy": "", "product_details": ["The breathable engineered mesh upper has targeted zones for support", "A Cushlon 3.0 foam midsole with a Zoom Air unit in the forefoot for cushioning and stability", "A durable Waffle outsole for grip and stability", "A midfoot support system for enhanced arch support to control pronation", "What''s new? The new Cushlon 3.0 foam underfoot and a higher stack height make it our most stable and supportive model yet.", "Weight: Approx. 289g (men''s size 9)", "Heel-to-toe drop: 10mm", "MR-10 Last—Our best, most consistent fit", "Not intended for use as personal protective equipment (PPE)", "We softened the materials on the inside of the heel, collar and tongue, so that any part of the shoe that''s touching your ankle feels smooth and comfortable.", "Single-layer mesh provides breathability and durability.", "The durable rubber sole has grooves in the forefoot to create flexibility, and vertical grooves down the side help create stability.", "Cinched-down laces", "Moulded heel", "Weight: 322g (men''s size 9)", "Heel-to-toe drop: 10mm", "Not intended for use as personal protective equipment (PPE)", "Colour Shown: Black/Iron Grey/White", "Style: DZ3488-002", "Country/Region of Origin: Vietnam"]}','https://static.nike.com/a/images/c_limit,w_592,f_auto/t_product_v1/6c8f8b93-fce2-4c6d-a597-2ddb06dfa4b7/AIR+ZOOM+STRUCTURE+25+WIDE.png',79,361.46,'2024-12-22 15:28:42.02095','2024-12-22 15:28:42.02095','running','men'),
	 ('2244e90e-8e70-4dd8-9e39-d05c0881e355','Nike Zoom Fly 6','{"title": "", "benefits": ["ZoomX foam, Nike''s lightest and most responsive foam, delivers our most energy return with every stride you take.", "The full-length carbon-fibre plate increases efficiency and responsiveness.", "The thin rubber outsole is lightweight and grippy on the road.", "Weight: 265g approx. (men''s UK 9)", "Heel-to-toe drop: 8mm", "Synthetic leather on upper", "Not intended for use as personal protective equipment (PPE)", "Colour Shown: Black/Light Smoke Grey/White", "Style: FN8454-001", "Country/Region of Origin: Vietnam"], "description": "The Zoom Fly 6 is with you every step of your run. Lighter than the Zoom Fly 5, its responsive ZoomX foam adds energy return to each stride, while a carbon-fibre plate helps propel you to the finishing line.", "current_price": "4,999,000₫4,999,000₫4,999,000₫", "reason_to_buy": "", "product_details": ["Weight: 265g approx. (men''s UK 9)", "Heel-to-toe drop: 8mm", "Synthetic leather on upper", "Not intended for use as personal protective equipment (PPE)", "Colour Shown: Black/Light Smoke Grey/White", "Style: FN8454-001", "Country/Region of Origin: Vietnam"]}','https://static.nike.com/a/images/c_limit,w_592,f_auto/t_product_v1/4e5fb8b2-1146-492e-b7fa-190b6a6c8b20/ZOOM+FLY+6.png',80,417.35,'2024-12-22 15:28:42.022508','2024-12-22 15:28:42.022508','running','men'),
	 ('e576fb3a-7327-4731-9828-ba3cfd557630','Nike Pegasus EasyOn','{"title": "", "benefits": ["The engineered toggle gives you an adjustable fit.", "Upgraded breathable engineered mesh upper", "ReactX foam midsole surrounds forefoot and heel Air Zoom units for an energised ride.", "A signature Waffle-inspired rubber outsole for traction and flexibility.", "A plush collar, tongue and sockliner for a secure and comfortable fit.", "What''s new? All-new ReactX foam midsole is 13% more responsive than previous React technology.", "Crafted for performance and planet, ReactX foam is engineered to reduce its carbon footprint by at least 43% in a pair of midsoles due to reduced manufacturing process energy compared with prior React foam. The carbon footprint of ReactX is based on cradle-to-gate assessment reviewed by PRé Sustainability B.V. and Intertek China. Other midsole components such as airbags, plates or other foam formulations were not considered.", "Weight: approx. 312g (men''s UK 9)", "Heel-to-toe drop: 10mm", "Colour Shown: Black/Anthracite/Photon Dust/White", "Style: FQ7837-002", "Country/Region of Origin: Vietnam"], "description": "Responsive cushioning in the Pegasus provides an energised ride for everyday road running. Experience lighter-weight energy return with dual Air Zoom units and a ReactX foam midsole. Plus, improved engineered mesh on the upper decreases weight and increases breathability.", "current_price": "3,829,000₫3,829,000₫3,829,000₫", "reason_to_buy": "", "product_details": ["The engineered toggle gives you an adjustable fit.", "Upgraded breathable engineered mesh upper", "ReactX foam midsole surrounds forefoot and heel Air Zoom units for an energised ride.", "A signature Waffle-inspired rubber outsole for traction and flexibility.", "A plush collar, tongue and sockliner for a secure and comfortable fit.", "What''s new? All-new ReactX foam midsole is 13% more responsive than previous React technology.", "Crafted for performance and planet, ReactX foam is engineered to reduce its carbon footprint by at least 43% in a pair of midsoles due to reduced manufacturing process energy compared with prior React foam. The carbon footprint of ReactX is based on cradle-to-gate assessment reviewed by PRé Sustainability B.V. and Intertek China. Other midsole components such as airbags, plates or other foam formulations were not considered.", "Weight: approx. 312g (men''s UK 9)", "Heel-to-toe drop: 10mm", "Colour Shown: Black/Anthracite/Photon Dust/White", "Style: FQ7837-002", "Country/Region of Origin: Vietnam"]}','https://static.nike.com/a/images/c_limit,w_592,f_auto/t_product_v1/31c82b86-3a33-4d54-88d9-cd52ebcfb5b2/PEGASUS+EASYON.png',84,265.73,'2024-12-22 15:28:42.023186','2024-12-22 15:28:42.023186','running','men'),
	 ('4f727b3f-6341-4783-9eac-c7ba1d1a2503','Nike Interact Run EasyOn','{"title": "", "benefits": ["We created the rubber outsole using runner-informed data for traction where you need it.", "The overlays on the toe offer durability.", "Weight: 269g approx. (men''s UK 9)", "Heel-to-toe drop: 10mm", "Colour Shown: Black/Black/White", "Style: FV5590-001", "Country/Region of Origin: Vietnam"], "description": "Can you see the future? Fast-forward your footsteps in the cutting-edge Nike Interact Run. It''s set up with all the running goodness you need: a lightweight Flyknit upper, soft foam midsole and comfort where it counts. Scan the QR code on the tongue with your phone, and check out our online introduction to the Nike Interact Run''s ins and outs. Plus, the laceless EasyOn entry has a bendable heel for a hands-free fit and the stretchy Flyknit stretches to accommodate all types of feet.", "current_price": "2,349,000₫2,349,000₫2,349,000₫", "reason_to_buy": "", "product_details": ["Weight: 269g approx. (men''s UK 9)", "Heel-to-toe drop: 10mm", "Colour Shown: Black/Black/White", "Style: FV5590-001", "Country/Region of Origin: Vietnam"]}','https://static.nike.com/a/images/c_limit,w_592,f_auto/t_product_v1/187e02b8-726c-4546-aae2-4744dae0761c/NIKE+INTERACT+RUN+EASYON.png',83,426.89,'2024-12-22 15:28:42.023875','2024-12-22 15:28:42.023875','running','men'),
	 ('c099a794-236a-4ff0-9b40-f345446db8bc','Sabrina 2 EP','{"title": "", "benefits": ["Colour Shown: Sport Red/College Navy/White", "Style: FZ1517-600", "Country/Region of Origin: Vietnam"], "description": "Sabrina Ionescu''s success is no secret. Her game is based on living in the gym, getting in rep after rep to perfect her craft. The Sabrina 2 sets you up to do more, so you''re ready to go when it''s game time. Our newest Cushlon foam helps keep you fresh, Air Zoom cushioning adds the pop and sticky traction helps you create that next-level distance. Sabrina''s handed you the tools. Time to go to work. With its extra-durable rubber outsole, this version gives you traction for outdoor courts.", "current_price": "3,829,000₫3,829,000₫3,829,000₫", "reason_to_buy": "", "product_details": ["Colour Shown: Sport Red/College Navy/White", "Style: FZ1517-600", "Country/Region of Origin: Vietnam"]}','https://static.nike.com/a/images/c_limit,w_592,f_auto/t_product_v1/882c21ec-b405-4e45-92d3-111a108e0cf0/SABRINA+2+EP.png',58,370.33,'2024-12-22 15:29:12.989899','2024-12-22 15:29:12.989899','basketball','women'),
	 ('c33adaba-8657-4a89-ad5a-875550dc069e','Nike Vomero 17 ''Talaria''','{"title": "", "benefits": ["A new engineered mesh upper for soft breathability", "A dual-density midsole with ZoomX foam stacked on top of Cushlon 3.0 foam for a comfortable ride", "A redesigned Waffle-inspired outsole with break points for a smooth, flexible stride", "A plush tongue and lining for a comfortably snug feel", "What''s New? The new stacked foam midsole with premium ZoomX on top of Cushlon 3.0 foam to amplify cushioned comfort.", "Weight: approx. 298g (men''s size 9)", "Heel-to-toe drop: 10mm", "MR-10 Last—Our best, most consistent fit", "Not intended for use as personal protective equipment (PPE)", "Colour Shown: Volt/White/Bright Crimson/Black", "Style: FZ8587-700", "Country/Region of Origin: China"], "description": "Maximum cushioning provides a comfortable ride for everyday runs. Experience enhanced comfort in this latest version, with a dual-density midsole made with a combination of ZoomX underfoot and Cushlon 3.0 foam throughout. Plus, a new engineered mesh upper offers more breathability.", "current_price": "4,699,000₫4,699,000₫4,699,000₫", "reason_to_buy": "", "product_details": ["Weight: approx. 298g (men''s size 9)", "Heel-to-toe drop: 10mm", "MR-10 Last—Our best, most consistent fit", "Not intended for use as personal protective equipment (PPE)", "Colour Shown: Volt/White/Bright Crimson/Black", "Style: FZ8587-700", "Country/Region of Origin: China"]}','https://static.nike.com/a/images/c_limit,w_592,f_auto/t_product_v1/230b8e64-8eb0-4568-aaed-d0142f97dc70/NIKE+VOMERO+17+TALARIA.png',69,409.46,'2024-12-22 15:28:42.024565','2024-12-22 15:28:42.024565','running','men'),
	 ('bbeaedc9-9563-477b-ab05-ab0e7c66a70d','Nike Interact Run SE','{"title": "", "benefits": ["We created the rubber outsole using runner-informed data for traction where you need it.", "The overlays on the toe offer durability.", "Weight: 260g (men''s size 9)", "Heel-to-toe drop: 10mm", "Colour Shown: Total Orange/Football Grey/Black/Volt", "Style: HJ4294-800", "Country/Region of Origin: Vietnam"], "description": "Can you see the future? Fast-forward your footsteps in the cutting-edge Nike Interact Run. It''s set up with all the running goodness you need: a lightweight Flyknit upper, soft foam midsole and comfort where it counts. Scan the QR code on the tongue with your phone, and check out our online introduction to the Nike Interact Run''s ins and outs.", "current_price": "2,349,000₫2,349,000₫2,349,000₫", "reason_to_buy": "", "product_details": ["Weight: 260g (men''s size 9)", "Heel-to-toe drop: 10mm", "Colour Shown: Total Orange/Football Grey/Black/Volt", "Style: HJ4294-800", "Country/Region of Origin: Vietnam"]}','https://static.nike.com/a/images/c_limit,w_592,f_auto/t_product_v1/0096a56b-5421-4ff5-aff4-8499b15607e6/NIKE+INTERACT+RUN+SE.png',65,416.45,'2024-12-22 15:28:42.025258','2024-12-22 15:28:42.025258','running','men'),
	 ('db51c548-c253-4718-9a08-bf1d9477e27c','Nike Journey Run PRM','{"title": "", "benefits": ["Engineered mesh helps your feet feel secure.", "Extra cushioning in the heel and soft touch points in the tongue and collar add comfort.", "The rubber outsole provides traction for your miles.", "Reflective design film on the side of the upper", "Weight: 288g approx. (men''s UK 9)", "Heel-to-toe drop: 11.1mm", "Not intended for use as personal protective equipment (PPE)", "Colour Shown: Hyper Crimson/Wolf Grey/Safety Orange/Metallic Silver", "Style: HQ2936-800", "Country/Region of Origin: Vietnam"], "description": "Enjoy every step, route and jaunt—day or night—in this winterized Nike Journey Run. It''ll have you striding and smiling on punishing pavements, thanks to an extra-high foam stack and super-soft ComfiRide cushioning. Plus, a reflective design film on the side lights up your route.", "current_price": "2,779,000₫2,779,000₫2,779,000₫", "reason_to_buy": "", "product_details": ["Reflective design film on the side of the upper", "Weight: 288g approx. (men''s UK 9)", "Heel-to-toe drop: 11.1mm", "Not intended for use as personal protective equipment (PPE)", "Colour Shown: Hyper Crimson/Wolf Grey/Safety Orange/Metallic Silver", "Style: HQ2936-800", "Country/Region of Origin: Vietnam"]}','https://static.nike.com/a/images/c_limit,w_592,f_auto/t_product_v1/7e4337dc-813f-49ec-9350-268226221e41/NIKE+JOURNEY+RUN+PRM.png',92,385.72,'2024-12-22 15:28:42.026616','2024-12-22 15:28:42.026616','running','men'),
	 ('22ee881e-242e-4213-8797-1c5933193844','Nike Winflo 11 PRM','{"title": "", "benefits": ["A breathable engineered mesh upper", "A Cushlon 3.0 foam midsole with a full-length Nike Air unit", "A rubber Waffle-inspired outsole for reliable traction", "What''s new? A spacious forefoot, a wider heel and even better breathability.", "Reflective design paint on the midsole", "Reflective-design laces", "Not intended for use as personal protective equipment (PPE)", "Weight: 325g approx. (men''s size 9)", "Heel-to-toe drop: 10mm", "MR-10 Last—Our best, most consistent fit", "Colour Shown: Hyper Crimson/Safety Orange/Metallic Silver", "Style: HQ2940-800", "Country/Region of Origin: Vietnam"], "description": "Responsive cushioning in the winterized Winflo provides a balanced ride for runs, day or night. Experience energy return with a combination of Cushlon 3.0 foam and a full-length Nike Air unit in the midsole. Plus, reflective paint on the midsole extends onto the upper to light up your route.", "current_price": "3,239,000₫3,239,000₫3,239,000₫", "reason_to_buy": "", "product_details": ["A breathable engineered mesh upper", "A Cushlon 3.0 foam midsole with a full-length Nike Air unit", "A rubber Waffle-inspired outsole for reliable traction", "What''s new? A spacious forefoot, a wider heel and even better breathability.", "Reflective design paint on the midsole", "Reflective-design laces", "Not intended for use as personal protective equipment (PPE)", "Weight: 325g approx. (men''s size 9)", "Heel-to-toe drop: 10mm", "MR-10 Last—Our best, most consistent fit", "Colour Shown: Hyper Crimson/Safety Orange/Metallic Silver", "Style: HQ2940-800", "Country/Region of Origin: Vietnam"]}','https://static.nike.com/a/images/c_limit,w_592,f_auto/t_product_v1/80968f6e-58d1-4aa2-913b-0a57d16badf3/NIKE+AIR+WINFLO+11+PRM.png',56,278.21,'2024-12-22 15:28:42.02732','2024-12-22 15:28:42.02732','running','men'),
	 ('88fb2e6f-c565-471d-8c2c-7bcf0d35abb8','LeBron XXII ''Crown Jewel'' EP','{"title": "", "benefits": ["Synthetic leather upper", "Multi-directional traction pattern", "Colour Shown: White/Medium Ash/Hot Lava/Volt Glow", "Style: FZ1095-101", "Country/Region of Origin: China"], "description": "LeBron isn''t slowing down any time soon. The open-court nightmare is as fast and spry as ever. But even Bron needs support when he''s at full throttle. That''s why we levelled up the LeBron 22. Newly implemented saddle wings offer optimal midfoot stability. They complement the heel and forefoot Air Zoom units, so the King can keep pushing the sport forwards. This version is inspired by LeBron''s relationship with his youngest son and the sense of clarity it brings. With its extra-durable rubber outsole, this version gives you traction for outdoor courts.", "current_price": "5,279,000₫5,279,000₫5,279,000₫", "reason_to_buy": "", "product_details": ["Synthetic leather upper", "Multi-directional traction pattern", "Colour Shown: White/Medium Ash/Hot Lava/Volt Glow", "Style: FZ1095-101", "Country/Region of Origin: China"]}','https://static.nike.com/a/images/c_limit,w_592,f_auto/t_product_v1/91a51763-80fe-488e-a5b2-8f9aff4c9794/LEBRON+XXII+EP.png',79,469.37,'2024-12-22 15:29:12.980961','2024-12-22 15:29:12.980961','basketball','women');
INSERT INTO public."PRODUCT" ("PRODUCT_ID","PRODUCT_NAME","PRODUCT_DESCRIPTION","PRODUCT_IMAGE","PRODUCT_QUANTITY","PRODUCT_PRICE","CREATED_AT","UPDATED_AT","PRODUCT_CATEGORY","GENDER") VALUES
	 ('fb9a1d1c-1b4a-4b36-a0d6-ce350aaaa68a','Nike Pegasus 41','{"title": "", "benefits": ["Upgraded breathable engineered mesh upper", "ReactX foam midsole surrounds forefoot and heel Air Zoom units for an energised ride.", "Signature waffle-inspired rubber outsole for traction and flexibility", "A plush collar, tongue and sockliner for a secure and comfortable fit", "What''s new? All-new ReactX foam midsole is 13% more responsive than previous React technology.", "Crafted for performance and planet, ReactX foam is engineered to reduce its carbon footprint by at least 43% in a pair of midsoles due to reduced manufacturing process energy compared with prior React foam. The carbon footprint of ReactX is based on a cradle-to-gate assessment reviewed by PRé Sustainability B.V. and Intertek China. Other midsole components such as airbags, plates or other foam formulations were not considered.", "Weight: Approx. 297g (Men''s size 9)", "Heel-to-toe drop: 10mm", "MR-10 last—our best, most consistent fit (same as Pegasus 40)", "Reflective design details", "Not intended for use as personal protective equipment (PPE)", "Colour Shown: Black/Sail/Volt/Glacier Blue", "Style: HQ3452-041", "Country/Region of Origin: China"], "description": "Responsive cushioning in the Pegasus provides an energised ride for everyday road running. Experience lighter-weight energy return with dual Air Zoom units and a ReactX foam midsole. Plus, improved engineered mesh on the upper decreases weight and increases breathability.", "current_price": "3,829,000₫3,829,000₫3,829,000₫", "reason_to_buy": "", "product_details": ["Upgraded breathable engineered mesh upper", "ReactX foam midsole surrounds forefoot and heel Air Zoom units for an energised ride.", "Signature waffle-inspired rubber outsole for traction and flexibility", "A plush collar, tongue and sockliner for a secure and comfortable fit", "What''s new? All-new ReactX foam midsole is 13% more responsive than previous React technology.", "Crafted for performance and planet, ReactX foam is engineered to reduce its carbon footprint by at least 43% in a pair of midsoles due to reduced manufacturing process energy compared with prior React foam. The carbon footprint of ReactX is based on a cradle-to-gate assessment reviewed by PRé Sustainability B.V. and Intertek China. Other midsole components such as airbags, plates or other foam formulations were not considered.", "Weight: Approx. 297g (Men''s size 9)", "Heel-to-toe drop: 10mm", "MR-10 last—our best, most consistent fit (same as Pegasus 40)", "Reflective design details", "Not intended for use as personal protective equipment (PPE)", "Colour Shown: Black/Sail/Volt/Glacier Blue", "Style: HQ3452-041", "Country/Region of Origin: China"]}','https://static.nike.com/a/images/c_limit,w_592,f_auto/t_product_v1/af0ea0dd-b4b9-4e0b-b1a3-ecbffa87440f/AIR+ZOOM+PEGASUS+41.png',99,495.99,'2024-12-22 15:28:42.027972','2024-12-22 15:28:42.027972','running','men'),
	 ('d9a6cfc2-7bed-4004-afea-71d6b2f6ac6d','Nike Invincible 3','{"title": "", "benefits": ["A breathable Flyknit upper for a secure fit without bulk", "The high and wide ZoomX foam midsole cushions on impact", "A Waffle outsole for durable traction", "Extra cushioning around contact points at the heel and tongue", "What''s new? A wider and taller ZoomX foam midsole for maximum comfort and sleek all-round design updates.", "Weight: Approx. 309g (men''s size 9)", "Heel-to-toe drop: 9mm", "Not intended for use as personal protective equipment (PPE)", "Colour Shown: Dark Stucco/Khaki/Neutral Olive/Baroque Brown", "Style: FZ3654-053", "Country/Region of Origin: Vietnam"], "description": "Maximum cushioning provides our most comfortable ride for everyday runs. Experience a breathable Flyknit upper and the robust platform of lightweight ZoomX foam that softens impact. Plus, the midsole of this model is wider and taller than the last for even more cushioned comfort.", "current_price": "4,471,199₫4,471,199₫4,471,199₫", "reason_to_buy": "", "product_details": ["A breathable Flyknit upper for a secure fit without bulk", "The high and wide ZoomX foam midsole cushions on impact", "A Waffle outsole for durable traction", "Extra cushioning around contact points at the heel and tongue", "What''s new? A wider and taller ZoomX foam midsole for maximum comfort and sleek all-round design updates.", "Weight: Approx. 309g (men''s size 9)", "Heel-to-toe drop: 9mm", "Not intended for use as personal protective equipment (PPE)", "Colour Shown: Dark Stucco/Khaki/Neutral Olive/Baroque Brown", "Style: FZ3654-053", "Country/Region of Origin: Vietnam"]}','https://static.nike.com/a/images/c_limit,w_592,f_auto/t_product_v1/dd62f510-4f88-4218-b630-8a6cf250f6fb/NIKE+ZOOMX+INVINCIBLE+RUN+FK+3.png',51,409.59,'2024-12-22 15:28:42.028733','2024-12-22 15:28:42.028733','running','men'),
	 ('fa5ef78c-84f3-4d8b-b95e-9a6aa405994f','Nike Winflo 10','{"title": "", "benefits": ["A breathable engineered mesh upper", "Encapsulated Nike Air cushioning for a springy feel", "A rubber Waffle-inspired outsole for reliable traction", "An elastic midfoot band to accommodate a variety of fits and activities", "What''s new? A revamped toe box and added cushioning on the collar and tongue for a better fit.", "Weight: Approx. 296g (men''s size 9)", "Heel-to-toe drop: 10mm", "MR-10 Last—Our best, most consistent fit", "Not intended for use as personal protective equipment (PPE)", "The engineered mesh—stronger and more flexible than ordinary mesh—improves hand feel and comfort while maintaining a lightweight, breathable feel.", "Overlays at the toe add a layer of durability.", "The tongue is connected to the upper''s inner lining for a secure feel.", "Weight: 296g (men''s size 9)", "Heel-to-toe drop: 10mm", "Colour Shown: Wolf Grey/Smoke Grey/Black/Volt", "Style: DV4022-007", "Country/Region of Origin: Vietnam"], "description": "The responsive cushioning provides a springy ride for everyday runs. Experience energy return with encapsulated Nike Air cushioning and an accommodating fit with an elastic midfoot band. Plus, a revamped toe box offers improved comfort and fit.", "current_price": "2,343,199₫2,343,199₫2,343,199₫", "reason_to_buy": "", "product_details": ["A breathable engineered mesh upper", "Encapsulated Nike Air cushioning for a springy feel", "A rubber Waffle-inspired outsole for reliable traction", "An elastic midfoot band to accommodate a variety of fits and activities", "What''s new? A revamped toe box and added cushioning on the collar and tongue for a better fit.", "Weight: Approx. 296g (men''s size 9)", "Heel-to-toe drop: 10mm", "MR-10 Last—Our best, most consistent fit", "Not intended for use as personal protective equipment (PPE)", "The engineered mesh—stronger and more flexible than ordinary mesh—improves hand feel and comfort while maintaining a lightweight, breathable feel.", "Overlays at the toe add a layer of durability.", "The tongue is connected to the upper''s inner lining for a secure feel.", "Weight: 296g (men''s size 9)", "Heel-to-toe drop: 10mm", "Colour Shown: Wolf Grey/Smoke Grey/Black/Volt", "Style: DV4022-007", "Country/Region of Origin: Vietnam"]}','https://static.nike.com/a/images/c_limit,w_592,f_auto/t_product_v1/449867af-17e8-4f80-b424-1533f8d753f0/AIR+WINFLO+10.png',58,467.06,'2024-12-22 15:28:42.029417','2024-12-22 15:28:42.029417','running','men'),
	 ('55297d46-93d5-46c8-a0a5-58b57f99f248','Nike React Phantom Run Flyknit 2','{"title": "", "benefits": ["Rubber on the outsole helps deliver better traction and durability.", "Moulding around the heel keeps you feeling stable, so you can focus on your route.", "Colour Shown: Sail/White/Light Bone/Black", "Style: DV2139-100", "Country/Region of Origin: Vietnam"], "description": "Go the distance with comfy confidence in every step. Building on the foundation of its predecessor, this shoe expands on its laceless design by adding secure support that feels like it disappears on your foot. More foam means better cushioning, helping keep you comfortable as you run.", "current_price": "3,287,199₫3,287,199₫3,287,199₫", "reason_to_buy": "", "product_details": ["Rubber on the outsole helps deliver better traction and durability.", "Moulding around the heel keeps you feeling stable, so you can focus on your route.", "Colour Shown: Sail/White/Light Bone/Black", "Style: DV2139-100", "Country/Region of Origin: Vietnam"]}','https://static.nike.com/a/images/c_limit,w_592,f_auto/t_product_v1/6b46ee80-6ebd-4935-8798-ff2665962bc0/NIKE+REACT+PHANTOM+RUN+FK+2.png',68,428.77,'2024-12-22 15:28:42.03007','2024-12-22 15:28:42.03007','running','men'),
	 ('0c735ed1-c773-4d0e-8843-e7db6841f216','Nike Zoom Superfly Elite 2','{"title": "", "benefits": ["Ideal for 100m–400m sprinters", "World Athletics approved", "Colour Shown: Racer Blue/Lime Blast/Safety Orange/White", "Style: CD4382-400", "Country/Region of Origin: China"], "description": "The Nike Zoom Superfly Elite 2 delivers a high-tech design for the track.Ultra-lightweight fabric helps keep you cool, while a spike plate with 8 removable pins provides grip to power through the finish.", "current_price": "3,086,299₫3,086,299₫3,086,299₫", "reason_to_buy": "", "product_details": ["Ideal for 100m–400m sprinters", "World Athletics approved", "Colour Shown: Racer Blue/Lime Blast/Safety Orange/White", "Style: CD4382-400", "Country/Region of Origin: China"]}','https://static.nike.com/a/images/c_limit,w_592,f_auto/t_product_v1/ab537277-cbf7-4ce0-98cf-f104427dd2c5/NIKE+ZOOM+SUPERFLY+ELITE+2.png',82,355.29,'2024-12-22 15:28:42.030811','2024-12-22 15:28:42.030811','running','men'),
	 ('1ce22b37-d74f-480b-a7d1-5c7c3d8807a6','G.T. Hustle Academy EP','{"title": "", "benefits": ["Colour Shown: College Navy/Psychic Blue/Racer Blue/White", "Style: FJ7808-401", "Country/Region of Origin: Vietnam"], "description": "The G.T. Hustle Academy helps keep you fast, wherever your next game is. A full Flyknit upper works with responsive foams to help you feel fresh on the court. With its extra-durable rubber outsole, this version gives you traction for outdoor courts.", "current_price": "2,649,000₫2,649,000₫2,649,000₫", "reason_to_buy": "", "product_details": ["Colour Shown: College Navy/Psychic Blue/Racer Blue/White", "Style: FJ7808-401", "Country/Region of Origin: Vietnam"]}','https://static.nike.com/a/images/c_limit,w_592,f_auto/t_product_v1/8891df66-d876-4c0f-9426-54d6216a9045/G.T.+HUSTLE+ACADEMY+EP.png',62,205.68,'2024-12-22 15:29:12.990861','2024-12-22 15:29:12.990861','basketball','women'),
	 ('f8900e72-806d-4e2b-b352-2132df753804','LeBron XXII ''Currency'' EP','{"title": "", "benefits": ["A breathable dimensional mesh on the upper", "Multi-directional traction pattern", "Colour Shown: White/Green Glow/Pink Foam/Baltic Blue", "Style: FZ1098-100", "Country/Region of Origin: China"], "description": "LeBron isn''t slowing down any time soon. The open-court nightmare is as fast and spry as ever. But even Bron needs support when he''s at full throttle. That''s why we levelled up the LeBron 22. Newly implemented saddle wings offer optimal midfoot stability. They complement the heel and forefoot Air Zoom units, so the King can keep pushing the sport forwards. This version nods to one of LeBron''s favourite board games and his willingness to make deposits in the everyday grind that pays dividends. With its extra-durable rubber outsole, this version gives you traction for outdoor courts.", "current_price": "5,869,000₫5,869,000₫5,869,000₫", "reason_to_buy": "", "product_details": ["A breathable dimensional mesh on the upper", "Multi-directional traction pattern", "Colour Shown: White/Green Glow/Pink Foam/Baltic Blue", "Style: FZ1098-100", "Country/Region of Origin: China"]}','https://static.nike.com/a/images/c_limit,w_592,f_auto/t_product_v1/24a62e35-a0ac-4bdb-b864-1e6ca358bc3b/LEBRON+XXII+QS+EP.png',82,458.27,'2024-12-22 15:29:12.982354','2024-12-22 15:29:12.982354','basketball','women'),
	 ('0184103c-fa0a-4e9a-80ff-c4236b9506a3','Ja 2 ''Foundation'' EP','{"title": "", "benefits": ["Extra ankle padding gives you comfort when landing and taking off.", "Raised foam collar adds extra cosiness around your Achilles heel.", "Colour Shown: Black/Light Smoke Grey/Light Lemon Twist/Phantom", "Style: FD7327-001", "Country/Region of Origin: China"], "description": "Ja puts in the work to be great so he can be at his best when the game''s on the line. That''s why we gave the Ja 2 a lighter design. It works with Air Zoom cushioning to help keep him fresh when he''s in the lab. And the tractor tyre-inspired traction helps him change direction with ease. Ja''s about that grind. Are you? With its extra-durable rubber outsole, this version gives you traction for outdoor courts.", "current_price": "3,519,000₫3,519,000₫3,519,000₫", "reason_to_buy": "", "product_details": ["Colour Shown: Black/Light Smoke Grey/Light Lemon Twist/Phantom", "Style: FD7327-001", "Country/Region of Origin: China"]}','https://static.nike.com/a/images/c_limit,w_592,f_auto/t_product_v1/641e2959-1529-4157-9801-0e92e043782a/JA+2+EP.png',50,346.62,'2024-12-22 15:29:12.983567','2024-12-22 15:29:12.983567','basketball','women'),
	 ('b9e8ff2d-9725-4b5b-9ae2-8302915bca3a','Giannis Immortality 4 EP','{"title": "", "benefits": ["Colour Shown: White/Pure Platinum/Black", "Style: FQ3681-100", "Country/Region of Origin: China"], "description": "The Giannis Immortality 4 is for the multi-faceted player. The sleek, supportive heel shape is combined with an upgraded traction pattern from the previous iteration to help keep you making all those game-changing plays. With its extra-durable rubber outsole, this version gives you traction for outdoor courts.", "current_price": "2,349,000₫2,349,000₫2,349,000₫", "reason_to_buy": "", "product_details": ["Colour Shown: White/Pure Platinum/Black", "Style: FQ3681-100", "Country/Region of Origin: China"]}','https://static.nike.com/a/images/c_limit,w_592,f_auto/t_product_v1/3042f129-ff49-4328-80cb-62b8ed05e9bf/GIANNIS+IMMORTALITY+4+EP.png',63,253.83,'2024-12-22 15:29:12.993936','2024-12-22 15:29:12.993936','basketball','women'),
	 ('2c41de8a-fcb6-4975-ae64-8fdf92db4b47','Ja 2 ''Nightmare'' EP','{"title": "", "benefits": ["Extra ankle padding gives you comfort when landing and taking off.", "Raised foam collar adds extra cosiness around your Achilles heel.", "Colour Shown: University Red/Black/Jade Horizon/Celestial Gold", "Style: HQ2637-600", "Country/Region of Origin: China"], "description": "Ja puts in the work to be great so he can be at his best when the game''s on the line. That''s why we gave the Ja 2 a lighter design. It works with Air Zoom cushioning to help keep him fresh when he''s in the lab. And the tractor tyre-inspired traction helps him change direction with ease. Ja''s about that grind. Are you? With its extra-durable rubber outsole, this version gives you traction for outdoor courts. This gory, grimy design pays homage to Ja''s spooky status as an unsolvable mismatch on the floor.", "current_price": "3,829,000₫3,829,000₫3,829,000₫", "reason_to_buy": "", "product_details": ["Colour Shown: University Red/Black/Jade Horizon/Celestial Gold", "Style: HQ2637-600", "Country/Region of Origin: China"]}','https://static.nike.com/a/images/c_limit,w_592,f_auto/t_product_v1/0170bf4f-3211-4860-956e-c0cd974e10a9/JA+2+NIGHTMARE+EP.png',68,308.36,'2024-12-22 15:29:12.98471','2024-12-22 15:29:12.98471','basketball','women');
