INSERT INTO public."PRODUCT" ("PRODUCT_ID","PRODUCT_NAME","PRODUCT_DESCRIPTION","PRODUCT_IMAGE","PRODUCT_QUANTITY","PRODUCT_PRICE","CREATED_AT","UPDATED_AT","PRODUCT_CATEGORY","GENDER") VALUES
	 ('e16b9186-c828-4f9a-93eb-d3e9ca022c46','Nike Free RN By You','{"title": "", "benefits": null, "description": "", "current_price": "", "reason_to_buy": "", "product_details": null}','https://static.nike.com/a/images/c_limit,w_592,f_auto/t_product_v1/48bd90d4-6785-4128-9314-669d54457e67/W+NIKE+FREE+RN+FK+NN+NBY.png',75,337.43,'2024-12-22 15:34:30.913851','2024-12-22 15:34:30.913851','running','women'),
	 ('731583d6-3d3a-4bd5-aa62-08418a7824fd','Nike Air Max 270','{"title": "", "benefits": ["The Max Air 270 unit delivers unrivalled, all-day comfort.", "Woven and synthetic fabric on the upper provides a lightweight fit and airy feel.", "The foam midsole feels soft and comfortable.", "The stretchy inner sleeve and booty-like construction creates a personalised fit.", "Rubber on the outsole adds traction and durability.", "Mesh details for an airy feel", "Synthetic and textile upper.", "Pull tab", "Colour Shown: White/Pale Ivory/Muslin/Black", "Style: AH6789-123", "Country/Region of Origin: Indonesia"], "description": "Nike''s first lifestyle Air Max brings you style, comfort and big attitude in the Nike Air Max 270. The design draws inspiration from Air Max icons, showcasing Nike''s greatest innovation with its large window and fresh array of colours.", "current_price": "4,409,000₫4,409,000₫4,409,000₫", "reason_to_buy": "", "product_details": ["Mesh details for an airy feel", "Synthetic and textile upper.", "Pull tab", "Colour Shown: White/Pale Ivory/Muslin/Black", "Style: AH6789-123", "Country/Region of Origin: Indonesia"]}','https://static.nike.com/a/images/c_limit,w_592,f_auto/t_product_v1/e16f8f2d-7b05-4f39-ad55-7bd3444fc724/W+AIR+MAX+270.png',70,269.65,'2024-12-22 15:32:46.630182','2024-12-22 15:32:46.630182','lifestyle','women'),
	 ('fab714ef-93de-4f67-80c2-9e4c0a2cc126','Nike Offcourt Adjust','{"title": "", "benefits": ["Contoured footbed cradles your foot to help keep it in place.", "Dual-density foam provides lightweight cushioning.", "Hook-and-loop strap is lined with soft fabric for extra comfort.", "Logo label doubles as a pull tab to help open the strap.", "Outsole features a pivot circle pattern for durability and traction.", "Colour Shown: Black/Black/White", "Style: DQ9624-001", "Country/Region of Origin: Vietnam"], "description": "Post game, errands and more—adjust your comfort on the go. The adjustable, padded strap lets you perfect your fit, while the lightweight foam midsole brings first-class comfort to your feet.", "current_price": "1,329,000₫1,329,000₫1,329,000₫", "reason_to_buy": "", "product_details": ["Colour Shown: Black/Black/White", "Style: DQ9624-001", "Country/Region of Origin: Vietnam"]}','https://static.nike.com/a/images/c_limit,w_592,f_auto/t_product_v1/22dbb81f-bb9b-43a9-a854-cf1e4ca4a2c0/NIKE+OFFCOURT+ADJUST+SLIDE.png',61,327.63,'2024-12-22 15:32:46.630894','2024-12-22 15:32:46.630894','lifestyle','women'),
	 ('26a19b1a-a83a-4b31-b0bc-733d5ea3f5f8','Nike Dunk Low Retro','{"title": "", "benefits": ["Colours let you rep your favourite university teams.", "Leather upper ages to soft perfection.", "Foam midsole offers lightweight, responsive cushioning.", "Padded, low-cut collar looks sleek and feels great.", "Rubber outsole with classic hoops pivot circle adds durable traction and heritage style.", "Colour Shown: Coconut Milk/Gym Red/Sail/University Blue", "Style: DV0833-113", "Country/Region of Origin: Indonesia"], "description": "Recognising the Dunk''s roots as the top-ranking university-team sneaker, the Be True To Your School Pack looks to the original ad campaign for inspiration. Colours represent top-flight universities, while crisp leather has the perfect amount of sheen to make ''em a hands-down win. So lace up and show off that varsity spirit. Are you game?", "current_price": "2,929,000₫2,929,000₫2,929,000₫", "reason_to_buy": "", "product_details": ["Colour Shown: Coconut Milk/Gym Red/Sail/University Blue", "Style: DV0833-113", "Country/Region of Origin: Indonesia"]}','https://static.nike.com/a/images/c_limit,w_592,f_auto/t_product_v1/b11d1156-fc6b-4ef4-bf7f-e5f34752cbe3/NIKE+DUNK+LOW+RETRO.png',50,351.65,'2024-12-22 15:32:46.631562','2024-12-22 15:32:46.631562','lifestyle','women'),
	 ('9339702d-3b8c-45ee-a47d-ea62914b0026','Nike Calm','{"title": "", "benefits": ["Contoured design is made from a single piece of foam for a smooth, seamless feel.", "Textured footbed provides grip to help keep your feet in place.", "Outer shell is made from water-friendly foam that is easy to clean.", "Rubber outsole gives you excellent traction even on slippery surfaces.", "Colour Shown: Black/Black", "Style: FD4115-001", "Country/Region of Origin: Indonesia"], "description": "Enjoy a calm, comfortable experience—wherever your day off takes you. Made from soft yet supportive foam, the minimal design makes these flip-flops easy to wear. And they''ve got a textured footbed to help keep your feet in place.", "current_price": "1,479,000₫1,479,000₫1,479,000₫", "reason_to_buy": "", "product_details": ["Colour Shown: Black/Black", "Style: FD4115-001", "Country/Region of Origin: Indonesia"]}','https://static.nike.com/a/images/c_limit,w_592,f_auto/t_product_v1/e598ee00-5894-4347-b49a-0161dbe82c86/W+NIKE+CALM+FLIP+FLOP.png',98,351.28,'2024-12-22 15:32:46.632193','2024-12-22 15:32:46.632193','lifestyle','women'),
	 ('68d13402-a0e3-4a6a-a3e8-743b9b202f68','Nike Air Max 90 GORE-TEX','{"title": "", "benefits": ["The textile upper with leather and synthetic overlays creates a layered look.", "Originally designed for performance running, visible Nike Air cushioning puts the history of comfort beneath your feet.", "Rubber Waffle outsole delivers durable traction and heritage style.", "Foam midsole", "Padded collar", "Colour Shown: Cacao Wow/Khaki/Black/Light Orewood Brown", "Style: FD5810-201", "Country/Region of Origin: Vietnam"], "description": "Lace up and feel the legacy. These AM90s will keep up with you on all your adventures thanks to a mix of GORE-TEX and mesh materials. Worn by presidents, revolutionised through collabs and celebrated through rare colourways, the Waffle sole, striking visuals and Nike Air cushioning keep it alive and well.", "current_price": "4,699,000₫4,699,000₫4,699,000₫", "reason_to_buy": "", "product_details": ["Foam midsole", "Padded collar", "Colour Shown: Cacao Wow/Khaki/Black/Light Orewood Brown", "Style: FD5810-201", "Country/Region of Origin: Vietnam"]}','https://static.nike.com/a/images/c_limit,w_592,f_auto/t_product_v1/bd9c6a93-264b-48d5-8ccc-f62db7eb657c/AIR+MAX+90+GTX.png',88,400.07,'2024-12-22 15:32:46.632813','2024-12-22 15:32:46.632813','lifestyle','women'),
	 ('74e1c1e5-6d36-4029-b3b6-fb5b35a616b3','Nike SB Zoom Janoski OG+','{"title": "", "benefits": ["Suede upper is soft and durable.", "Vulcanised construction fuses the sole to the upper for a flexible, broken-in feel.", "Snappy and responsive, Zoom Air cushioning helps provide a quick-off-the-ground sensation.", "2 sets of laces", "Colour Shown: Black/Black/White/White", "Style: FD6757-001", "Country/Region of Origin: China, Indonesia"], "description": "Coming in hot after a year of R&R (research and redesign), the Janoski continues the journey of Stefan''s signature skateboarding line. The skate-specific tread helps deliver great boardfeel and flick. A re-engineered upper helps give you better fit and comfort, opening the door to next-level performance.", "current_price": "2,779,000₫2,779,000₫2,779,000₫", "reason_to_buy": "", "product_details": ["2 sets of laces", "Colour Shown: Black/Black/White/White", "Style: FD6757-001", "Country/Region of Origin: China, Indonesia"]}','https://static.nike.com/a/images/c_limit,w_592,f_auto/t_product_v1/03c91279-e797-4cd7-879f-d082448a0c97/NIKE+SB+ZOOM+JANOSKI+OG%2B.png',75,217.57,'2024-12-22 15:32:46.633426','2024-12-22 15:32:46.633426','lifestyle','women'),
	 ('420b6b68-2831-4d17-8784-2f7c32e55243','Nike InfinityRN 4 By You','{"title": "", "benefits": null, "description": "", "current_price": "", "reason_to_buy": "", "product_details": null}','https://static.nike.com/a/images/c_limit,w_592,f_auto/t_product_v1/996d29f4-b351-44c5-b750-e3b48752280e/NIKE+REACTX+INFINITY+RUN+4+NBY.png',77,382.77,'2024-12-22 15:34:30.914572','2024-12-22 15:34:30.914572','running','women'),
	 ('a5e2c37d-c434-48f5-b06d-8e7744c595ac','Nike Air Force 1 Dance','{"title": "", "benefits": ["The premium leather upper with hidden rubber pods in high-wear areas adds extra durability.", "Originally designed for performance hoops, Nike Air cushioning delivers lasting comfort.", "The rubber outsole with pivot circles provides great traction.", "The flex grooves allow you to move naturally from heel to toe.", "The flipped logo on the heel and tongue is the right way up when you''re upside down during freeze poses.", "Padded collar", "Foam midsole", "Rubber outsole", "Colour Shown: White/White/Metallic Silver/White", "Style: FJ7409-100", "Country/Region of Origin: Vietnam"], "description": "These Air Force 1 are made to move. Designed to meet the needs of dancers, this version puts Air cushioning in the forefoot for customised support. A contoured upper with a thicker collar helps lock down your midfoot and heel, while a more flexible outsole lets you show off your footwork with ease.", "current_price": "3,829,000₫3,829,000₫3,829,000₫", "reason_to_buy": "", "product_details": ["Padded collar", "Foam midsole", "Rubber outsole", "Colour Shown: White/White/Metallic Silver/White", "Style: FJ7409-100", "Country/Region of Origin: Vietnam"]}','https://static.nike.com/a/images/c_limit,w_592,f_auto/t_product_v1/61fea48b-6bde-4656-9291-fc7e4b56032c/W+AIR+FORCE+1+DANCE.png',87,456.05,'2024-12-22 15:32:46.634061','2024-12-22 15:32:46.634061','lifestyle','women'),
	 ('2e334200-d531-4408-9416-9fefe3af7b3a','Air Jordan Legacy 312 Low','{"title": "", "benefits": ["Real and synthetic leather in the upper offers durability and structure.", "The midfoot strap adds bold branding and helps secure your fit.", "The visible Nike Air unit in the heel helps provide comfortable cushioning.", "Rubber sole has a full cupsole stitch for exceptional durability.", "Rubber in the outsole helps give you traction on various surfaces.", "Colour Shown: Sail/Cement Grey/Black/Football Grey", "Style: FQ7827-101", "Country/Region of Origin: Indonesia"], "description": "Who doesn''t love a good mash-up? Taking elements from the AJ1, AJ3 and the Nike Air Alpha Force, these kicks encompass the best of the best. Iconic details (check out that elephant print and midfoot strap) honour MJ''s time in Chicago''s 312 area code. With premium materials and Nike Air cushioning, this is the beginning of a whole new legacy.", "current_price": "4,109,000₫4,109,000₫4,109,000₫", "reason_to_buy": "", "product_details": ["Colour Shown: Sail/Cement Grey/Black/Football Grey", "Style: FQ7827-101", "Country/Region of Origin: Indonesia"]}','https://static.nike.com/a/images/c_limit,w_592,f_auto/t_product_v1/u_126ab356-44d8-4a06-89b4-fcdcc8df0245,c_scale,fl_relative,w_1.0,h_1.0,fl_layer_apply/3fc11760-b158-4cc5-a3f4-54df8a725684/WMNS+AIR+JORDAN+LEGACY+312+LOW.png',95,224.43,'2024-12-22 15:32:46.634897','2024-12-22 15:32:46.634897','lifestyle','women');
INSERT INTO public."PRODUCT" ("PRODUCT_ID","PRODUCT_NAME","PRODUCT_DESCRIPTION","PRODUCT_IMAGE","PRODUCT_QUANTITY","PRODUCT_PRICE","CREATED_AT","UPDATED_AT","PRODUCT_CATEGORY","GENDER") VALUES
	 ('6e345dd9-782d-4e03-b4f5-6de289d3d9a7','Nike Blazer Roam Mid','{"title": "", "benefits": ["The synthetic leather upper is smooth and durable.", "The Nike SB toe box is wider for a more comfortable fit.", "A wide, curved opening creates ease of entry, even with bulky socks.", "The rubber mudguard helps protect your shoes from winter elements.", "The foam midsole keeps the shoe from feeling too heavy.", "The rubber Waffle outsole with grippy lugs delivers durable traction across all city surfaces.", "Foam midsole", "Rubber outsole", "Colour Shown: Black/Racer Blue", "Style: FQ9065-001", "Country/Region of Origin: Indonesia"], "description": "The classic Blazer, adapted for winter elements. An easy-entry design and a wide toe box make layering with thick socks a breeze. And that heavy-duty outsole? It cuts through slush, salt and whatever else the city throws your way.", "current_price": "3,829,000₫3,829,000₫3,829,000₫", "reason_to_buy": "", "product_details": ["Foam midsole", "Rubber outsole", "Colour Shown: Black/Racer Blue", "Style: FQ9065-001", "Country/Region of Origin: Indonesia"]}','https://static.nike.com/a/images/c_limit,w_592,f_auto/t_product_v1/c2e8a907-83d0-4ad3-9237-8c7c77894174/W+NIKE+BLAZER+ROAM+MID.png',96,399.22,'2024-12-22 15:32:46.635718','2024-12-22 15:32:46.635718','lifestyle','women'),
	 ('10fd70bb-82ae-48bf-a002-c14b20705b55','Nike Air Force 1 ''07 LX','{"title": "", "benefits": ["Smooth leather with metallic gold Swooshes creates a premium, layered look.", "Originally designed for performance hoops, Nike Air cushioning delivers lasting comfort.", "Padded, low-cut collar looks sleek and feels great.", "Rubber sole has a full cupsole stitch for exceptional durability.", "Colour Shown: Sail/Sail/Metallic Gold/Sail", "Style: FV3654-111", "Country/Region of Origin: Vietnam"], "description": "Take your love for the game with you wherever you go. Crossing hardwood comfort with off-court flair, these kicks put a fresh spin on a hoops classic with leather and perfectly placed mini Swooshes. Of course, we kept the same era-echoing ''80s construction and Nike Air cushioning you know and love for that legendary AF-1 feel. Go ahead—slip into a slam dunk.", "current_price": "3,519,000₫3,519,000₫3,519,000₫", "reason_to_buy": "", "product_details": ["Colour Shown: Sail/Sail/Metallic Gold/Sail", "Style: FV3654-111", "Country/Region of Origin: Vietnam"]}','https://static.nike.com/a/images/c_limit,w_592,f_auto/t_product_v1/8722be57-c8e4-468a-9f81-bb7aa52043e7/WMNS+AIR+FORCE+1+%2707+LX.png',81,454.45,'2024-12-22 15:32:46.636849','2024-12-22 15:32:46.636849','lifestyle','women'),
	 ('b77b59ef-a540-4811-aea8-db4625b04781','Nike SB PS8','{"title": "", "benefits": ["The HART outsole uses less rubber compound than our other XDR rubber technologies—without sacrificing durability and abrasion resistance.", "The updated Flyplate creates longevity in the foam and performs like it''s fresh out of the box.", "Snappy and responsive, Air Zoom cushioning helps provide a quick-off-the-ground sensation.", "Foam midsole", "Rubber outsole", "Colour Shown: Obsidian/Squadron Blue/Navy/Phantom", "Style: FV8493-400", "Country/Region of Origin: China"], "description": "Designed to put in the work out of the box, the PS8 delivers with a 3-pronged approach. Starting with a layered Flyknit construction with leather in high-wear areas, it offers a broken-in feel that retains its shape session after session. An updated Flyplate is integrated into the sole, providing a responsive feel that works in tandem with the HART (High Abrasion Rubber Tech) outsole. HART uses less rubber to help make the outsole lighter and more flexible. The PS8 wraps it all in a low-top silhouette with Nike Running aesthetics, heritage pattern and all the technical details that matter.", "current_price": "3,519,000₫3,519,000₫3,519,000₫", "reason_to_buy": "", "product_details": ["Foam midsole", "Rubber outsole", "Colour Shown: Obsidian/Squadron Blue/Navy/Phantom", "Style: FV8493-400", "Country/Region of Origin: China"]}','https://static.nike.com/a/images/c_limit,w_592,f_auto/t_product_v1/e1c513d9-e695-45e1-8c74-19da12da96b4/NIKE+SB+PS8.png',83,377.40,'2024-12-22 15:32:46.638067','2024-12-22 15:32:46.638067','lifestyle','women'),
	 ('1501e0ea-1a9a-42bd-9925-cd9c562da5c3','Nike InfinityRN 4 By You','{"title": "", "benefits": null, "description": "", "current_price": "", "reason_to_buy": "", "product_details": null}','https://static.nike.com/a/images/c_limit,w_592,f_auto/t_product_v1/97332d0e-3967-4e1a-807c-b55ad8e7ab28/NIKE+REACTX+INFINITY+RUN+4+NBY.png',53,408.17,'2024-12-22 15:34:30.915239','2024-12-22 15:34:30.915239','running','women'),
	 ('e3c01a15-8ce5-4d29-9044-835bbdf4ed45','Nike Dunk Low','{"title": "", "benefits": ["Hits of genuine leather add a premium look and durability.", "Upper softens and gains vintage character with wear.", "Foam midsole offers lightweight, responsive cushioning.", "Rubber outsole with classic pivot circle adds durable traction and heritage style.", "Foam insole", "Not intended for use as personal protective equipment (PPE)", "Colour Shown: Muslin/Pale Ivory/Laser Orange/Team Gold", "Style: FZ2552-100", "Country/Region of Origin: Indonesia"], "description": "The Dunk Low pair iconic colour-blocking with premium materials and plush padding for game-changing comfort that lasts. The possibilities are endless—how will you wear your Dunks?", "current_price": "3,519,000₫3,519,000₫3,519,000₫", "reason_to_buy": "", "product_details": ["Foam insole", "Not intended for use as personal protective equipment (PPE)", "Colour Shown: Muslin/Pale Ivory/Laser Orange/Team Gold", "Style: FZ2552-100", "Country/Region of Origin: Indonesia"]}','https://static.nike.com/a/images/c_limit,w_592,f_auto/t_product_v1/f13622e3-1435-4856-86a1-cef0419cd288/W+NIKE+DUNK+LOW.png',90,434.63,'2024-12-22 15:32:46.639084','2024-12-22 15:32:46.639084','lifestyle','women'),
	 ('537f0053-3e99-4743-ac24-43154eced49f','Nike V2K Run GORE-TEX','{"title": "", "benefits": ["The mesh upper feels light and airy, while waterproof GORE-TEX helps keep you warm and dry.", "The dual-density foam midsole provides lasting comfort.", "Translucent plastic accents reference the classic Nike Vomero 5.", "Rubber outsole gives you durable traction.", "Foam midsole", "Rubber outsole", "Colour Shown: Light Iron Ore/Light Bone/Khaki/Light Iron Ore", "Style: FZ2622-002", "Country/Region of Origin: Vietnam"], "description": "This winterized version of the V2K adds a GORE-TEX upper to an early 2000s running style. For more Y2K energy, its chunky heel provides ample cushioning while keeping the fit lightweight.", "current_price": "4,409,000₫4,409,000₫4,409,000₫", "reason_to_buy": "", "product_details": ["Foam midsole", "Rubber outsole", "Colour Shown: Light Iron Ore/Light Bone/Khaki/Light Iron Ore", "Style: FZ2622-002", "Country/Region of Origin: Vietnam"]}','https://static.nike.com/a/images/c_limit,w_592,f_auto/t_product_v1/5c2e795f-1b81-4203-82d2-663031b713e8/W+NIKE+V2K+RUN+GTX.png',80,238.44,'2024-12-22 15:32:46.64018','2024-12-22 15:32:46.64018','lifestyle','women'),
	 ('cb410c33-1ca7-4ea2-8b04-27897a373daa','Nike Air Max SC','{"title": "", "benefits": ["The real and synthetic leather is combined with airy knits and mesh for a durable construction that''s breathable and comfortable enough to wear all day.", "Originally designed for running, the Max Air unit delivers lightweight cushioning with every step.", "Foam midsole adds cushioning that lasts.", "Rubber outsole provides traction and durability.", "Foam midsole", "Rubber outsole", "Colour Shown: Black/Hemp/White/Sesame", "Style: FZ2649-001", "Country/Region of Origin: Indonesia"], "description": "With its familiar design lines, heritage athletics aesthetic and visible Max Air cushioning, the Nike Air Max SC is the perfect way to finish any outfit. Smooth leather and lightweight knit textiles add depth and durability, while animal-print accents make for a wild detail.", "current_price": "2,779,000₫2,779,000₫2,779,000₫", "reason_to_buy": "", "product_details": ["Foam midsole", "Rubber outsole", "Colour Shown: Black/Hemp/White/Sesame", "Style: FZ2649-001", "Country/Region of Origin: Indonesia"]}','https://static.nike.com/a/images/c_limit,w_592,f_auto/t_product_v1/65f6d1ca-efb3-4016-b294-af4ed9f33a7e/WMNS+NIKE+AIR+MAX+SC.png',55,252.11,'2024-12-22 15:32:46.641231','2024-12-22 15:32:46.641231','lifestyle','women'),
	 ('b45d7236-373e-45c1-9947-46d25ed9234c','Nike Air More Uptempo Low','{"title": "", "benefits": ["Synthetic leather upper adds durability, while perforations and a mesh tongue keep it breathable.", "Originally designed for performance hoops, Max Air units add lightweight cushioning.", "Elastic straps over the tongue keep your style sharp whether you rock these laced or unlaced.", "Foam midsole", "Rubber outsole", "Colour Shown: White/White", "Style: FZ3055-100", "Country/Region of Origin: Vietnam"], "description": "With high-flying basketball style and graffiti-inspired graphics, the Air More Uptempo is sure to turn heads on and off the court. This low-top version pairs Air cushioning and a padded collar, so you feel as good as you look.", "current_price": "4,999,000₫4,999,000₫4,999,000₫", "reason_to_buy": "", "product_details": ["Foam midsole", "Rubber outsole", "Colour Shown: White/White", "Style: FZ3055-100", "Country/Region of Origin: Vietnam"]}','https://static.nike.com/a/images/c_limit,w_592,f_auto/t_product_v1/ade3ccfd-27a4-4507-9f08-62a7f88043e3/AIR+MORE+UPTEMPO+LOW.png',78,254.53,'2024-12-22 15:32:46.642128','2024-12-22 15:32:46.642128','lifestyle','women'),
	 ('2fcc844c-3459-42d5-bbc8-c7cd6727972c','Nike Air More Uptempo','{"title": "", "benefits": ["A padded strap with perforations feels plush and airy.", "Visible Nike Air technology provides cushioning with every step.", "The foam footbed is contoured to help keep your foot in place.", "Durable rubber outsole features the grip pattern from the original Uptempo.", "Foam midsole", "Rubber outsole", "Colour Shown: Flax/Gum Medium Brown/Clear/Flax", "Style: FZ3113-200", "Country/Region of Origin: Vietnam"], "description": "Keeping the graffiti-styled graphics from the original, your favourite hoops look gets transformed into slides. The Air More Uptempo combines Nike Air cushioning and a plush strap with airy perforations, providing breathable comfort you can slip on and go.", "current_price": "2,649,000₫2,649,000₫2,649,000₫", "reason_to_buy": "", "product_details": ["Foam midsole", "Rubber outsole", "Colour Shown: Flax/Gum Medium Brown/Clear/Flax", "Style: FZ3113-200", "Country/Region of Origin: Vietnam"]}','https://static.nike.com/a/images/c_limit,w_592,f_auto/t_product_v1/4be496ed-2d34-43ac-89b0-f1759c2984b2/AIR+MORE+UPTEMPO+SLIDE.png',80,392.81,'2024-12-22 15:32:46.642867','2024-12-22 15:32:46.642867','lifestyle','women'),
	 ('8112f1d5-5ca0-4e65-8c5d-7dc26dd5089a','Nike Burrow SE','{"title": "", "benefits": ["Foam midsole/outsole adds lasting comfort.", "Fleece-like material lines the inside (and insole) for added warmth and comfort.", "Outsole traction pattern helps on various surfaces.", "Colour Shown: Black/Black", "Style: FZ7939-001", "Country/Region of Origin: Indonesia"], "description": "Wherever you''re going, go cosy. The fleece-like lining helps keep you warm, and the marshmallow-soft foam midsole/outsole with grippy traction pattern adds spring to your step.", "current_price": "1,909,000₫1,909,000₫1,909,000₫", "reason_to_buy": "", "product_details": ["Colour Shown: Black/Black", "Style: FZ7939-001", "Country/Region of Origin: Indonesia"]}','https://static.nike.com/a/images/c_limit,w_592,f_auto/t_product_v1/1e3abe50-acac-49a0-b59b-465bec9eae39/W+NIKE+BURROW+SE.png',96,253.31,'2024-12-22 15:32:46.643563','2024-12-22 15:32:46.643563','lifestyle','women');
INSERT INTO public."PRODUCT" ("PRODUCT_ID","PRODUCT_NAME","PRODUCT_DESCRIPTION","PRODUCT_IMAGE","PRODUCT_QUANTITY","PRODUCT_PRICE","CREATED_AT","UPDATED_AT","PRODUCT_CATEGORY","GENDER") VALUES
	 ('b57a4ff4-d288-493a-a922-88b9545c4ce7','Nike Free RN By You','{"title": "", "benefits": null, "description": "", "current_price": "", "reason_to_buy": "", "product_details": null}','https://static.nike.com/a/images/c_limit,w_592,f_auto/t_product_v1/6edab495-a429-44ff-8971-1c4bcf822741/W+NIKE+FREE+RN+FK+NN+NBY.png',97,303.86,'2024-12-22 15:34:30.915961','2024-12-22 15:34:30.915961','running','women'),
	 ('3bf797d3-6b26-43d7-9911-5c49076efcee','Nike Pegasus 41 By You','{"title": "", "benefits": null, "description": "", "current_price": "", "reason_to_buy": "", "product_details": null}','https://static.nike.com/a/images/c_limit,w_592,f_auto/t_product_v1/aa950a0d-e1af-4a09-b139-cacb493aa748/W+AIR+ZOOM+PEGASUS+41+NBY.png',80,213.64,'2024-12-22 15:34:30.916783','2024-12-22 15:34:30.916783','running','women'),
	 ('263faf1a-0c29-4188-9bf5-4ceeda6f0099','Air Jordan 1 High Method of Make','{"title": "", "benefits": ["Real and synthetic leather in the upper adds durability and structure, while satin and canvas create texture and dimension.", "Nike Air technology absorbs impact for cushioning with every step.", "Rubber in the outsole helps give you durable traction.", "Two sets of laces let you personalise your style.", "Wings logo on the collar", "Stitched-down Swoosh logo", "Colour Shown: Pink Oxford/Atmosphere/Phantom/Legend Light Brown", "Style: FZ8779-600", "Country/Region of Origin: China"], "description": "The AJ1 High is always on point. But it''s safe to say this pair, which was inspired by pointe shoes, goes a little further in helping you stand out with style. We played with textures and proportions—check out the satin details and oversized Swoosh logo—to create a fresh take on an all-time favourite.", "current_price": "4,539,000₫4,539,000₫4,539,000₫", "reason_to_buy": "", "product_details": ["Wings logo on the collar", "Stitched-down Swoosh logo", "Colour Shown: Pink Oxford/Atmosphere/Phantom/Legend Light Brown", "Style: FZ8779-600", "Country/Region of Origin: China"]}','https://static.nike.com/a/images/c_limit,w_592,f_auto/t_product_v1/u_126ab356-44d8-4a06-89b4-fcdcc8df0245,c_scale,fl_relative,w_1.0,h_1.0,fl_layer_apply/1d9e7074-d6bd-4819-8777-64210904ae4c/WMNS+AIR+JORDAN+1+MM+HIGH.png',84,238.78,'2024-12-22 15:32:46.644529','2024-12-22 15:32:46.644529','lifestyle','women'),
	 ('a37f06fc-0125-496a-ad43-6ce76914ef8e','Nike Calm Printed','{"title": "", "benefits": ["Contoured design is made from a single piece of foam for a smooth, seamless feel.", "Textured footbed provides grip to help keep your feet in place.", "Outer shell is made from water-friendly foam that is easy to clean.", "Rubber outsole gives you excellent traction even on slippery surfaces.", "Colour Shown: Sail/Sail", "Style: HF1069-100", "Country/Region of Origin: Indonesia"], "description": "Enjoy a calm, comfortable experience—wherever your day off takes you. Made from soft yet supportive foam, the minimal design makes these slides easy to style with or without socks. And they''ve got a textured footbed to help keep your feet in place.", "current_price": "1,759,000₫1,759,000₫1,759,000₫", "reason_to_buy": "", "product_details": ["Colour Shown: Sail/Sail", "Style: HF1069-100", "Country/Region of Origin: Indonesia"]}','https://static.nike.com/a/images/c_limit,w_592,f_auto/t_product_v1/2eaf9244-1c35-4359-99d1-fe62488df4d4/W+NIKE+CALM+SLIDE+PRINT.png',72,373.25,'2024-12-22 15:32:46.645783','2024-12-22 15:32:46.645783','lifestyle','women'),
	 ('9806c6b3-195d-42d9-88dc-dd151d4031e3','Nike Waffle Debut','{"title": "", "benefits": ["Nylon and soft suede overlays nod to vintage running roots, while the textile underlays add durability.", "A plush foam midsole gives you an elevated look and all-day comfort.", "Rubber Waffle outsole adds durable traction and heritage style.", "Padded collar", "Exposed foam tongue", "Perforations on the heel", "Colour Shown: Phantom/Summit White/Black/Sesame", "Style: HF1856-001", "Country/Region of Origin: Indonesia"], "description": "Retro running style gets modernised in the Nike Waffle Debut. Era-echoing suede and nylon are paired with a modern wedge-shaped midsole and a pop of animal print for a look that feels fresh, but classic. Of course, we kept our tried, true and tested Waffle outsole on the bottom to add durable traction and a touch of character to every step.", "current_price": "2,189,000₫2,189,000₫2,189,000₫", "reason_to_buy": "", "product_details": ["Padded collar", "Exposed foam tongue", "Perforations on the heel", "Colour Shown: Phantom/Summit White/Black/Sesame", "Style: HF1856-001", "Country/Region of Origin: Indonesia"]}','https://static.nike.com/a/images/c_limit,w_592,f_auto/t_product_v1/be797e80-3338-4448-9fef-4aaf9fc8d104/WMNS+NIKE+WAFFLE+DEBUT.png',61,478.96,'2024-12-22 15:32:46.646725','2024-12-22 15:32:46.646725','lifestyle','women'),
	 ('149d99af-87f7-442a-a5fe-6f7a105c9efa','Jordan Stadium 90','{"title": "", "benefits": ["The real and synthetic leather add durability and structure to the upper.", "Moulded collar inspired by the AJ5 provides plush cushioning around your ankle.", "Tonal stitching above the midsole echoes the fire graphic from the AJ5.", "Rubber outsole draws from the AJ1 to give you durable traction.", "Colour Shown: White/Gym Red/Midnight Navy", "Style: HJ4406-100", "Country/Region of Origin: Vietnam"], "description": "You''re fearless. It''s in your DNA (and ours too). Celebrate what defines you in the Jordan Stadium 90. Iconic elements of the AJ1 and AJ5 (check out the moulded collar and midsole stitching) collide with modern construction and premium cushioning to create a new classic made with durability and comfort in mind.", "current_price": "4,109,000₫4,109,000₫4,109,000₫", "reason_to_buy": "", "product_details": ["Colour Shown: White/Gym Red/Midnight Navy", "Style: HJ4406-100", "Country/Region of Origin: Vietnam"]}','https://static.nike.com/a/images/c_limit,w_592,f_auto/t_product_v1/u_126ab356-44d8-4a06-89b4-fcdcc8df0245,c_scale,fl_relative,w_1.0,h_1.0,fl_layer_apply/b80d469e-55cc-43f1-b7ef-5b42112f6e76/WMNS+JORDAN+STADIUM+90.png',67,200.71,'2024-12-22 15:32:46.647528','2024-12-22 15:32:46.647528','lifestyle','women'),
	 ('d4e6391d-d7f3-4c79-b9c0-53cea65caf7d','Nike Air Max Plus SE','{"title": "", "benefits": ["Mesh upper with synthetic leather accents is durable and breathable.", "Midfoot arch band provides a supportive feel.", "Originally designed for performance running, Nike Air units provide lightweight cushioning that lasts.", "Rubber outsole gives you durable traction.", "Reflective design details", "Foam midsole", "Rubber outsole", "Not intended for use as personal protective equipment (PPE)", "Colour Shown: Black/Metallic Silver/Laser Crimson/Off-Noir", "Style: HJ9743-001", "Country/Region of Origin: Indonesia"], "description": "Let your attitude have the edge in the Air Max Plus. Its iconic caging adds heat to your look while airy mesh keeps you cool. And the visible cushioning lets you celebrate your defiant style in comfort. This premium version features metallic and accents with a reflective design.", "current_price": "5,279,000₫5,279,000₫5,279,000₫", "reason_to_buy": "", "product_details": ["Reflective design details", "Foam midsole", "Rubber outsole", "Not intended for use as personal protective equipment (PPE)", "Colour Shown: Black/Metallic Silver/Laser Crimson/Off-Noir", "Style: HJ9743-001", "Country/Region of Origin: Indonesia"]}','https://static.nike.com/a/images/c_limit,w_592,f_auto/t_product_v1/1b2663b6-239c-4c53-a5ee-a2494dd6df06/W+NIKE+AIR+MAX+PLUS+SE.png',50,414.80,'2024-12-22 15:32:46.648246','2024-12-22 15:32:46.648246','lifestyle','women'),
	 ('cf303835-4baf-47ed-9575-884eb4ac9a1e','Nike Invincible 3 By You','{"title": "", "benefits": null, "description": "", "current_price": "", "reason_to_buy": "", "product_details": null}','https://static.nike.com/a/images/c_limit,w_592,f_auto/t_product_v1/b6639443-978d-4e8f-8ccf-ca261e026ffc/W+ZOOMX+INVINCIBLE+RUN+3+NBY.png',90,261.10,'2024-12-22 15:34:30.917541','2024-12-22 15:34:30.917541','running','women'),
	 ('84fe07fe-30b9-4525-b319-49a94321aabf','Nike Pegasus Trail 5 By You','{"title": "", "benefits": null, "description": "", "current_price": "", "reason_to_buy": "", "product_details": null}','https://static.nike.com/a/images/c_limit,w_592,f_auto/t_product_v1/21897254-4510-4958-84c0-775adb7121c0/W+PEGASUS+TRAIL+5+WIDE+NBY.png',55,238.71,'2024-12-22 15:34:30.918276','2024-12-22 15:34:30.918276','running','women'),
	 ('a0067c21-3850-460e-a069-a83f6bcfbb82','Nike Air Pegasus 2005','{"title": "", "benefits": ["The upper mixes real and synthetic leather with textiles for a layered look built to last.", "Nike Air technology absorbs impact for cushioning with every step.", "Waffle-inspired pattern provides traction.", "Foam midsole", "Rubber outsole", "Reflective design details", "Not intended for use as personal protective equipment (PPE)", "Colour Shown: Sail/Phantom/Aquarius Blue/Anthracite", "Style: HM4348-100", "Country/Region of Origin: Vietnam"], "description": "The Peg''s familiar, just-for-you feel returns with a design ready for the streets. This edition has the same cushioning and comfort you love with a breezy look inspired by early noughties runners.", "current_price": "4,409,000₫4,409,000₫4,409,000₫", "reason_to_buy": "", "product_details": ["Foam midsole", "Rubber outsole", "Reflective design details", "Not intended for use as personal protective equipment (PPE)", "Colour Shown: Sail/Phantom/Aquarius Blue/Anthracite", "Style: HM4348-100", "Country/Region of Origin: Vietnam"]}','https://static.nike.com/a/images/c_limit,w_592,f_auto/t_product_v1/9af08aaf-7ee7-4fe2-8404-b095f311e738/NIKE+AIR+PEGASUS+2005.png',96,222.33,'2024-12-22 15:32:46.648993','2024-12-22 15:32:46.648993','lifestyle','women');
INSERT INTO public."PRODUCT" ("PRODUCT_ID","PRODUCT_NAME","PRODUCT_DESCRIPTION","PRODUCT_IMAGE","PRODUCT_QUANTITY","PRODUCT_PRICE","CREATED_AT","UPDATED_AT","PRODUCT_CATEGORY","GENDER") VALUES
	 ('a872246d-a4df-4a3b-a42e-5763fba93339','Nike Initiator','{"title": "", "benefits": ["Supportive overlays help centre your foot in the shoe.", "Soft lining enhances comfort.", "The foam midsole provides a soft, cushioned ride.", "Flex grooves in the outsole help you move freely.", "Colour Shown: Sail/Sail/Light Orewood Brown/Game Royal", "Style: HQ1183-141", "Country/Region of Origin: Vietnam"], "description": "Put in miles with the comfortable support of the Nike Initiator. It pairs a breathable upper with soft cushioning to help you hit your stride again and again.", "current_price": "2,499,000₫2,499,000₫2,499,000₫", "reason_to_buy": "", "product_details": ["Colour Shown: Sail/Sail/Light Orewood Brown/Game Royal", "Style: HQ1183-141", "Country/Region of Origin: Vietnam"]}','https://static.nike.com/a/images/c_limit,w_592,f_auto/t_product_v1/e39ebabe-1914-4421-8bce-bbf65246383b/WMNS+NIKE+INITIATOR.png',95,339.08,'2024-12-22 15:32:46.649698','2024-12-22 15:32:46.649698','lifestyle','women'),
	 ('d62065ea-e50f-4220-849e-d0ed918571ee','Nike Initiator','{"title": "", "benefits": ["Supportive overlays help centre your foot in the shoe.", "Foam midsole delivers a soft, cushioned ride.", "Flex grooves in the outsole help you move freely.", "Colour Shown: Summit White/Light Smoke Grey/Photon Dust/Ashen Slate", "Style: HQ1511-121", "Country/Region of Origin: Vietnam"], "description": "Put in miles with the comfortable support of the Nike Initiator. It has a breathable upper with a soft, cushioned design that helps you hit your stride with confidence.", "current_price": "2,499,000₫2,499,000₫2,499,000₫", "reason_to_buy": "", "product_details": ["Colour Shown: Summit White/Light Smoke Grey/Photon Dust/Ashen Slate", "Style: HQ1511-121", "Country/Region of Origin: Vietnam"]}','https://static.nike.com/a/images/c_limit,w_592,f_auto/t_product_v1/c454eb11-ebbc-4652-8c4c-2703160ba498/WMNS+NIKE+INITIATOR.png',74,499.10,'2024-12-22 15:32:46.650342','2024-12-22 15:32:46.650342','lifestyle','women'),
	 ('714d0f73-11bd-4507-a436-eb7d9cd89e94','Nike Air Max Excee','{"title": "", "benefits": ["The Max Air units add lasting cushioning and can be seen through 3 windows for a truly modern look.", "The elongated design lines honour the Air Max 90 and modernise these kicks in a fresh way.", "Stitched overlays add heritage styling and durability.", "Padded, low-cut collar looks sleek and feels comfortable.", "Foam midsole", "Rubber outsole", "Colour Shown: Summit White/White/Hemp/Black", "Style: HQ2115-100", "Country/Region of Origin: Vietnam"], "description": "Get into the groove with the Nike Air Max Excee. Inspired by the Nike Air Max 90, these kicks put a modern twist on a legendary icon through leopard-print details, elongated design lines and distorted proportions.", "current_price": "3,089,000₫3,089,000₫3,089,000₫", "reason_to_buy": "", "product_details": ["Foam midsole", "Rubber outsole", "Colour Shown: Summit White/White/Hemp/Black", "Style: HQ2115-100", "Country/Region of Origin: Vietnam"]}','https://static.nike.com/a/images/c_limit,w_592,f_auto/t_product_v1/e1684cf4-15d7-4d3c-b8e2-66c913d0143b/W+NIKE+AIR+MAX+EXCEE.png',55,271.09,'2024-12-22 15:32:46.65106','2024-12-22 15:32:46.65106','lifestyle','women'),
	 ('b1885a14-57c4-4d67-884b-5a0983cf5a63','Nike Zoom Vomero Roam','{"title": "", "benefits": ["Layers of textile and suede on the upper create a durable, comfortable fit.", "The lace toggle is easy to adjust and features a hook to keep it in place.", "The water-repellent finish and rubber mudguard help block the elements so your feet stay dry.", "The Nike Air Zoom units provide all-day cushioning.", "The HART (High Abrasion Rubber Tech) outsole uses less rubber compound than our other XDR rubber technologies—without sacrificing durability and abrasion resistance. Less material helps make the outsole lighter and more flexible.", "Pull tabs", "Reflective design details", "Foam midsole", "Rubber outsole", "Not intended for use as personal protective equipment (PPE)", "Colour Shown: Black/Black/Racer Blue/Black", "Style: HQ2181-004", "Country/Region of Origin: China"], "description": "Designed for city conditions, this winterized version of the Vomero is made for wet weather. Durable materials and a rubber mudguard work together to help safeguard your shoes from dirt and puddles. Plus, a chunky midsole gives you a visible boost of comfort and style wherever you wander.", "current_price": "5,279,000₫5,279,000₫5,279,000₫", "reason_to_buy": "", "product_details": ["Pull tabs", "Reflective design details", "Foam midsole", "Rubber outsole", "Not intended for use as personal protective equipment (PPE)", "Colour Shown: Black/Black/Racer Blue/Black", "Style: HQ2181-004", "Country/Region of Origin: China"]}','https://static.nike.com/a/images/c_limit,w_592,f_auto/t_product_v1/6828e5e6-81b1-42da-bc97-1827486a237c/W+NIKE+ZOOM+VOMERO+ROAM.png',57,287.56,'2024-12-22 15:32:46.651741','2024-12-22 15:32:46.651741','lifestyle','women'),
	 ('b73aee32-4071-410b-8cff-0cfdfb34fc59','Nike Air Max 2013','{"title": "", "benefits": ["Originally developed for performance running, visible Max Air cushioning delivers lasting comfort.", "Airy mesh details on the upper are reinforced with synthetic leather overlays for a highly ventilated, classic Nike look.", "Foam midsole has flex grooves for a supportive feel that lets you move freely.", "Colour Shown: Metallic Silver/Black/Flat Silver/Metallic Silver", "Style: HQ3025-001", "Country/Region of Origin: Vietnam"], "description": "The Air Max 2013 returns with mesh detailing and sporty, no-sew overlays to help keep you feeling fresh. Tried-and-tested Flywire lacing and classic full-length Max Air cushioning provide lasting comfort and support.", "current_price": "5,279,000₫5,279,000₫5,279,000₫", "reason_to_buy": "", "product_details": ["Colour Shown: Metallic Silver/Black/Flat Silver/Metallic Silver", "Style: HQ3025-001", "Country/Region of Origin: Vietnam"]}','https://static.nike.com/a/images/c_limit,w_592,f_auto/t_product_v1/75fd1299-c2c9-44c9-84a8-f55efca183de/AIR+MAX+2013.png',80,394.29,'2024-12-22 15:32:46.65246','2024-12-22 15:32:46.65246','lifestyle','women'),
	 ('89922deb-4015-49ad-80c3-58c67303bc35','Nike Air Max Excee','{"title": "", "benefits": ["Upper combines real and synthetic leather and textile for a durable, layered look.", "Max Air unit adds lasting cushioning and is visible through 3 windows for a truly modern look.", "Elongated design lines honour the Air Max 90 while modernising these kicks in a fresh way.", "Stitched overlays add heritage styling and durability.", "Padded, low-cut collar looks sleek and feels comfortable.", "Foam midsole", "Rubber outsole", "Colour Shown: White/Phantom/Sail/Vintage Green", "Style: HQ3411-100", "Country/Region of Origin: Vietnam"], "description": "Get into the groove with the Nike Air Max Excee''s subtle pops of colour and style that defies time. Inspired by the Nike Air Max 90, these kicks deliver a modern twist on a legendary icon through elongated design lines and distorted proportions.", "current_price": "2,929,000₫2,929,000₫2,929,000₫", "reason_to_buy": "", "product_details": ["Foam midsole", "Rubber outsole", "Colour Shown: White/Phantom/Sail/Vintage Green", "Style: HQ3411-100", "Country/Region of Origin: Vietnam"]}','https://static.nike.com/a/images/c_limit,w_592,f_auto/t_product_v1/7c8c54b9-cfab-4591-a56b-d6909a54904b/WMNS+NIKE+AIR+MAX+EXCEE.png',86,408.30,'2024-12-22 15:32:46.65374','2024-12-22 15:32:46.65374','lifestyle','women'),
	 ('b0d8bc8f-1d35-4ac5-bdf8-a14966717887','Nike Air Max 270','{"title": "", "benefits": ["Knit fabric on upper provides lightweight fit and airy feel to help your feet stay cool.", "Extra-large window to your Max Air unit gives you bold style and a look at the cushioning that helps deliver lasting comfort.", "Stretchy inner sleeve creates a fit that feels personalised.", "Pull tab on heel", "Foam midsole", "Colour Shown: White/Bicoastal/Phantom/Vintage Green", "Style: HQ3421-100", "Country/Region of Origin: Indonesia"], "description": "Legendary Air gets lifted. Our first lifestyle Air Max brings you comfort, bold style and 270 degrees of Max Air technology to showcase one of our greatest innovations yet. Add a lightweight, airy upper and low-cut collar, and you''ve got the perfect go-to kicks for everyday fun.", "current_price": "4,699,000₫4,699,000₫4,699,000₫", "reason_to_buy": "", "product_details": ["Pull tab on heel", "Foam midsole", "Colour Shown: White/Bicoastal/Phantom/Vintage Green", "Style: HQ3421-100", "Country/Region of Origin: Indonesia"]}','https://static.nike.com/a/images/c_limit,w_592,f_auto/t_product_v1/1518d6fb-ded7-45af-a879-6e1c130f1a95/W+AIR+MAX+270.png',97,485.82,'2024-12-22 15:32:46.654456','2024-12-22 15:32:46.654456','lifestyle','women'),
	 ('9569b28a-94fb-4fff-8444-aedeb65fb8d1','Nike Terrascout','{"title": "", "benefits": ["Classic laces", "Reflective design details", "Not intended for use as personal protective equipment (PPE)", "Colour Shown: Sand Drift/Light British Tan/Seafoam/Baroque Brown", "Style: HQ3472-122", "Country/Region of Origin: Indonesia"], "description": "Blaze new trails in the Nike Terrascout. Its textured mudguard helps keep the elements out, while a soft fleece lining helps your feet stay warm and cosy. Plus, a rugged rubber outsole gives you the grip you need when exploring new terrain.", "current_price": "2,419,000₫2,419,000₫2,419,000₫", "reason_to_buy": "", "product_details": ["Classic laces", "Reflective design details", "Not intended for use as personal protective equipment (PPE)", "Colour Shown: Sand Drift/Light British Tan/Seafoam/Baroque Brown", "Style: HQ3472-122", "Country/Region of Origin: Indonesia"]}','https://static.nike.com/a/images/c_limit,w_592,f_auto/t_product_v1/b2762ce4-fb6f-456a-b147-c05d150f0ae0/NIKE+TERRASCOUT+%28GS%29.png',53,438.26,'2024-12-22 15:32:46.655177','2024-12-22 15:32:46.655177','lifestyle','women'),
	 ('f1966019-c7dc-477f-888b-7b34d1de1e34','Nike V2K Run SE','{"title": "", "benefits": ["Leather and mesh upper feels light and airy.", "Dual-density foam midsole creates a comfortable ride.", "Translucent plastic accents reference the classic Nike Vomero 5.", "Rubber outsole gives you durable traction.", "Reflective design details", "Not intended for use as personal protective equipment (PPE)", "Colour Shown: White/Black/Team Red", "Style: HQ3500-100", "Country/Region of Origin: Vietnam"], "description": "The V2K is a look pulled straight from an early 2000s running catalogue. The chunky midsole and layered details add a perfectly vintage touch. And although the extra-cushioned heel looks like a throwback, the comfort is all modern.", "current_price": "3,519,000₫3,519,000₫3,519,000₫", "reason_to_buy": "", "product_details": ["Reflective design details", "Not intended for use as personal protective equipment (PPE)", "Colour Shown: White/Black/Team Red", "Style: HQ3500-100", "Country/Region of Origin: Vietnam"]}','https://static.nike.com/a/images/c_limit,w_592,f_auto/t_product_v1/239f124a-be1f-4d7f-bc25-3f369d74f219/W+NIKE+V2K+RUN+SE.png',60,481.79,'2024-12-22 15:32:46.655872','2024-12-22 15:32:46.655872','lifestyle','women'),
	 ('1e1a4014-04c6-4048-b8a8-fb3072e9e0ce','Nike Zoom Vomero 5','{"title": "", "benefits": ["Real and synthetic leathers on the upper add durability.", "The mesh panels and ventilation ports on heel help keep it light and breathable.", "Snappy and responsive, Air Zoom cushioning helps provide a quick-off-the-ground sensation.", "Plastic caging on the side adds support.", "Rubber outsole gives you durable traction.", "Reflective design details", "Not intended for use as personal protective equipment (PPE)", "Colour Shown: Platinum Violet/Light Violet Ore/Team Gold/Dark Raisin", "Style: HQ3643-019", "Country/Region of Origin: Vietnam"], "description": "Carve a new lane for yourself in the Vomero 5—your go-to for depth, durability and easy styling. The richly layered design includes textiles, leather and plastic accents that nod to the Y2K aesthetic.", "current_price": "4,699,000₫4,699,000₫4,699,000₫", "reason_to_buy": "", "product_details": ["Reflective design details", "Not intended for use as personal protective equipment (PPE)", "Colour Shown: Platinum Violet/Light Violet Ore/Team Gold/Dark Raisin", "Style: HQ3643-019", "Country/Region of Origin: Vietnam"]}','https://static.nike.com/a/images/c_limit,w_592,f_auto/t_product_v1/e0a6bba0-1188-4008-9a5e-5c5b52a5c9b9/NIKE+ZOOM+VOMERO+5.png',60,464.92,'2024-12-22 15:32:46.656554','2024-12-22 15:32:46.656554','lifestyle','women');
INSERT INTO public."PRODUCT" ("PRODUCT_ID","PRODUCT_NAME","PRODUCT_DESCRIPTION","PRODUCT_IMAGE","PRODUCT_QUANTITY","PRODUCT_PRICE","CREATED_AT","UPDATED_AT","PRODUCT_CATEGORY","GENDER") VALUES
	 ('aa9fe364-fc02-4046-8ffa-b04bd0e36ae3','Nike Zoom Vomero 5','{"title": "", "benefits": ["The ventilation ports on the heel help keep it light and breathable.", "Snappy and responsive, Air Zoom cushioning helps provide a quick-off-the-ground sensation.", "Plastic caging on the side adds support.", "Rubber outsole", "Reflective design details", "Not intended for use as personal protective equipment (PPE)", "Colour Shown: Metallic Silver/University Red/White/Black", "Style: HV0926-095", "Country/Region of Origin: Vietnam"], "description": "Carve a new lane for yourself in the Vomero 5—your go-to for depth, durability and easy styling. The richly layered design includes textiles, synthetic leather and plastic accents that nod to the Y2K aesthetic.", "current_price": "4,699,000₫4,699,000₫4,699,000₫", "reason_to_buy": "", "product_details": ["Rubber outsole", "Reflective design details", "Not intended for use as personal protective equipment (PPE)", "Colour Shown: Metallic Silver/University Red/White/Black", "Style: HV0926-095", "Country/Region of Origin: Vietnam"]}','https://static.nike.com/a/images/c_limit,w_592,f_auto/t_product_v1/6c221449-ac39-4a15-b24b-3fb6c1ff741c/NIKE+ZOOM+VOMERO+5.png',90,254.01,'2024-12-22 15:32:46.657297','2024-12-22 15:32:46.657297','lifestyle','women'),
	 ('0da2fb28-672e-4b45-b795-83661c765add','Nike Shox TL','{"title": "", "benefits": ["Nike Shox technology combines resilient, flexible columns with moderator plates for outstanding cushioning that compresses and regains its shape.", "Combination upper with full TPU cage is near-exact replica of the 2003 Nike Shox TL.", "Moulded overlays throughout midfoot provide support and snug fit.", "TPU plate in the heel between midsole and Nike Shox technology helps provide lateral stability and support.", "Foam midsole", "Rubber outsole", "Colour Shown: Metallic Platinum/Pink Foam/White/Pinksicle", "Style: HV2520-001", "Country/Region of Origin: Vietnam"], "description": "The Nike Shox TL takes mechanical cushioning to the next level. A recrafted version of the 2003 icon, it features breathable mesh and full-length Nike Shox technology for optimal impact absorption and a bold look on the streets.", "current_price": "5,279,000₫5,279,000₫5,279,000₫", "reason_to_buy": "", "product_details": ["Foam midsole", "Rubber outsole", "Colour Shown: Metallic Platinum/Pink Foam/White/Pinksicle", "Style: HV2520-001", "Country/Region of Origin: Vietnam"]}','https://static.nike.com/a/images/c_limit,w_592,f_auto/t_product_v1/292469d5-db4f-4c2c-af1a-0e764b02a030/WMNS+NIKE+SHOX+TL.png',90,394.25,'2024-12-22 15:32:46.6582','2024-12-22 15:32:46.6582','lifestyle','women'),
	 ('be0d8bdb-9c6b-42c0-a4dd-28af4b8ffac4','Nike P-6000','{"title": "", "benefits": ["Throwback design draws on Nike Pegasus 25 and Nike Pegasus 2006.", "The foam midsole adds a lifted, athletics-inspired stance and soft cushioning.", "The textile with leather and synthetic overlays help keep your feet cool while providing structure.", "Rubber outsole", "Reflective design details", "Not intended for use as personal protective equipment (PPE)", "Colour Shown: Burgundy Crush/Taupe Grey/Platinum Violet/Pink Foam", "Style: HV2522-600", "Country/Region of Origin: Vietnam"], "description": "A mash-up of Pegasus sneakers past, the P-6000 takes early 2000s running to modern heights. Featuring mixed materials and sporty lines, it''s the perfect blend of head-turning comfort and early aughties style.", "current_price": "2,929,000₫2,929,000₫2,929,000₫", "reason_to_buy": "", "product_details": ["Rubber outsole", "Reflective design details", "Not intended for use as personal protective equipment (PPE)", "Colour Shown: Burgundy Crush/Taupe Grey/Platinum Violet/Pink Foam", "Style: HV2522-600", "Country/Region of Origin: Vietnam"]}','https://static.nike.com/a/images/c_limit,w_592,f_auto/t_product_v1/6a336eb2-164e-4091-aa11-2fb817284081/WMNS+NIKE+P-6000.png',50,295.23,'2024-12-22 15:32:46.659212','2024-12-22 15:32:46.659212','lifestyle','women'),
	 ('445f6f7c-b48d-48bc-94f5-ebb99d5f4931','Nike Zoom Vomero 5','{"title": "", "benefits": ["The upper mixes real and synthetic leather for a layered look built to last.", "Mesh panels and ventilation ports on the heel keep it light and breathable.", "Snappy and responsive, Air Zoom cushioning helps provide a quick-off-the-ground sensation.", "Plastic caging on the side creates a supportive feel.", "Rubber outsole gives you durable traction.", "Reflective design details", "Not intended for use as personal protective equipment (PPE)", "Colour Shown: Sand Drift/Hemp/Black/Phantom", "Style: HV3880-126", "Country/Region of Origin: Indonesia"], "description": "Carve a new lane for yourself in the Zoom Vomero 5—your go-to for complexity, depth and easy styling. A nod to Y2K runners, this version''s richly layered vintage aesthetic includes textiles, leather and plastic accents that come together to make one of the coolest sneakers of the season.", "current_price": "4,999,000₫4,999,000₫4,999,000₫", "reason_to_buy": "", "product_details": ["Reflective design details", "Not intended for use as personal protective equipment (PPE)", "Colour Shown: Sand Drift/Hemp/Black/Phantom", "Style: HV3880-126", "Country/Region of Origin: Indonesia"]}','https://static.nike.com/a/images/c_limit,w_592,f_auto/t_product_v1/40f1bce6-a0b0-413b-9bbe-fa0930910cbc/W+NIKE+ZOOM+VOMERO+5.png',63,496.15,'2024-12-22 15:32:46.660019','2024-12-22 15:32:46.660019','lifestyle','women'),
	 ('d9fd9ff2-672a-42c7-9f08-66a091058dfd','Nike V2K Run','{"title": "", "benefits": ["Mixed materials add depth and durability.", "Dual-density foam midsole creates a comfortable ride.", "Translucent plastic accents reference the classic Nike Vomero 5.", "Rubber outsole gives you durable traction.", "Colour Shown: Sail/Sand Drift/Phantom/Sail", "Style: HV3917-133", "Country/Region of Origin: Vietnam"], "description": "The V2K is a look pulled straight from an early 2000s running catalogue. The chunky midsole and layered details add a perfectly vintage touch. And although the extra-cushioned heel looks like a throwback, the comfort is all modern.", "current_price": "3,519,000₫3,519,000₫3,519,000₫", "reason_to_buy": "", "product_details": ["Colour Shown: Sail/Sand Drift/Phantom/Sail", "Style: HV3917-133", "Country/Region of Origin: Vietnam"]}','https://static.nike.com/a/images/c_limit,w_592,f_auto/t_product_v1/e9a83d37-7783-47dd-b5f8-c18df710344f/W+NIKE+V2K+RUN.png',60,435.37,'2024-12-22 15:32:46.660727','2024-12-22 15:32:46.660727','lifestyle','women'),
	 ('06a75773-d10c-4533-b8a6-f4759b3101da','Nike Zoom Vomero Roam','{"title": "", "benefits": ["Layers of textile and suede on the upper create a durable, comfortable fit.", "The lace toggle is easy to adjust and features a hook to keep it in place.", "The water-repellent finish and rubber mudguard help block the elements so your feet stay dry.", "The Nike Air Zoom units provide all-day cushioning.", "The HART (High Abrasion Rubber Tech) outsole uses less rubber compound than our other XDR rubber technologies—without sacrificing durability and abrasion resistance. Less material helps make the outsole lighter and more flexible.", "Pull tabs", "Reflective design details", "Foam midsole", "Rubber outsole", "Not intended for use as personal protective equipment (PPE)", "Colour Shown: Summit White/Light Bone/Light Iron Ore/Summit White", "Style: HV6410-100", "Country/Region of Origin: China"], "description": "Designed for city conditions, this winterized version of the Vomero is made for wet weather. Durable materials and a rubber mudguard work together to help safeguard your shoes from dirt and puddles. Plus, a chunky midsole gives you a visible boost of comfort and style wherever you wander.", "current_price": "5,279,000₫5,279,000₫5,279,000₫", "reason_to_buy": "", "product_details": ["Pull tabs", "Reflective design details", "Foam midsole", "Rubber outsole", "Not intended for use as personal protective equipment (PPE)", "Colour Shown: Summit White/Light Bone/Light Iron Ore/Summit White", "Style: HV6410-100", "Country/Region of Origin: China"]}','https://static.nike.com/a/images/c_limit,w_592,f_auto/t_product_v1/b0d89796-9586-4dea-b4e2-ffc2bfaa8909/W+NIKE+ZOOM+VOMERO+ROAM.png',50,450.13,'2024-12-22 15:32:46.661431','2024-12-22 15:32:46.661431','lifestyle','women'),
	 ('813d60d9-d403-4588-8c11-e887c8e53501','Nike Pegasus Trail 5 By You','{"title": "", "benefits": null, "description": "", "current_price": "", "reason_to_buy": "", "product_details": null}','https://static.nike.com/a/images/c_limit,w_592,f_auto/t_product_v1/a77ea674-c8e0-4711-a95b-a7f78c09082e/W+PEGASUS+TRAIL+5+WIDE+NBY.png',96,342.73,'2024-12-22 15:34:30.919023','2024-12-22 15:34:30.919023','running','women'),
	 ('17403fcf-b0c0-4afd-8f78-f476e267826e','Nike Invincible 3 By You','{"title": "", "benefits": null, "description": "", "current_price": "", "reason_to_buy": "", "product_details": null}','https://static.nike.com/a/images/c_limit,w_592,f_auto/t_product_v1/7ed04347-be67-4d4b-a3b9-b0d3883c2daa/W+ZOOMX+INVINCIBLE+RUN+3+NBY.png',80,447.25,'2024-12-22 15:34:30.919724','2024-12-22 15:34:30.919724','running','women'),
	 ('280ac656-da85-4bc5-bf76-85ece4b62dcf','Nike Pegasus 41','{"title": "", "benefits": ["Upgraded breathable engineered mesh upper", "ReactX foam midsole surrounds forefoot and heel Air Zoom units for an energised ride.", "Signature waffle-inspired rubber outsole for traction and flexibility", "A plush collar, tongue and sockliner for a secure and comfortable fit", "What''s new? All-new ReactX foam midsole is 13% more responsive than previous React technology.", "Crafted for performance and planet, ReactX foam is engineered to reduce its carbon footprint by at least 43% in a pair of midsoles due to reduced manufacturing process energy compared with prior React foam. The carbon footprint of ReactX is based on cradle-to-gate assessment reviewed by PRé Sustainability B.V. and Intertek China. Other midsole components such as airbags, plates or other foam formulations were not considered.", "Weight: Approx. 251g (women''s size 5.5)", "Heel-to-toe drop: 10mm", "MR-10 last—our best, most consistent fit (same as Pegasus 40)", "Not intended for use as personal protective equipment (PPE)", "Colour Shown: Phantom/Light Pumice/Sail/Metallic Gold", "Style: FD2723-005", "Country/Region of Origin: Indonesia"], "description": "Responsive cushioning in the Pegasus provides an energised ride for everyday road running. Experience lighter-weight energy return with dual Air Zoom units and a ReactX foam midsole. Plus, improved engineered mesh on the upper decreases weight and increases breathability.", "current_price": "3,829,000₫3,829,000₫3,829,000₫", "reason_to_buy": "", "product_details": ["Upgraded breathable engineered mesh upper", "ReactX foam midsole surrounds forefoot and heel Air Zoom units for an energised ride.", "Signature waffle-inspired rubber outsole for traction and flexibility", "A plush collar, tongue and sockliner for a secure and comfortable fit", "What''s new? All-new ReactX foam midsole is 13% more responsive than previous React technology.", "Crafted for performance and planet, ReactX foam is engineered to reduce its carbon footprint by at least 43% in a pair of midsoles due to reduced manufacturing process energy compared with prior React foam. The carbon footprint of ReactX is based on cradle-to-gate assessment reviewed by PRé Sustainability B.V. and Intertek China. Other midsole components such as airbags, plates or other foam formulations were not considered.", "Weight: Approx. 251g (women''s size 5.5)", "Heel-to-toe drop: 10mm", "MR-10 last—our best, most consistent fit (same as Pegasus 40)", "Not intended for use as personal protective equipment (PPE)", "Colour Shown: Phantom/Light Pumice/Sail/Metallic Gold", "Style: FD2723-005", "Country/Region of Origin: Indonesia"]}','https://static.nike.com/a/images/c_limit,w_592,f_auto/t_product_v1/7358b1ee-dec1-46a2-9e49-0526c68194dd/W+AIR+ZOOM+PEGASUS+41.png',68,288.70,'2024-12-22 15:34:30.838758','2024-12-22 15:34:30.838758','running','women'),
	 ('bc9fea1a-fbf5-471c-9b57-df85d49dae63','Nike Downshifter 13','{"title": "", "benefits": ["Reflective design details", "Not intended for use as personal protective equipment (PPE)", "Colour Shown: Phantom/Summit White/Sail/Elemental Pink", "Style: FD6476-004", "Country/Region of Origin: Vietnam"], "description": "Whether you''re starting your running journey or an expert eager to switch up your pace, the Downshifter 13 is down for the ride. With a revamped upper, cushioning and durability, it helps you find that extra gear or take that first stride towards chasing down your goals.", "current_price": "2,069,000₫2,069,000₫2,069,000₫", "reason_to_buy": "", "product_details": ["Reflective design details", "Not intended for use as personal protective equipment (PPE)", "Colour Shown: Phantom/Summit White/Sail/Elemental Pink", "Style: FD6476-004", "Country/Region of Origin: Vietnam"]}','https://static.nike.com/a/images/c_limit,w_592,f_auto/t_product_v1/196768fe-810e-4b90-8e2c-963d9757337c/W+NIKE+DOWNSHIFTER+13.png',78,389.13,'2024-12-22 15:34:30.839968','2024-12-22 15:34:30.839968','running','women');
