INSERT INTO public."PRODUCT" ("PRODUCT_ID","PRODUCT_NAME","PRODUCT_DESCRIPTION","PRODUCT_IMAGE","PRODUCT_QUANTITY","PRODUCT_PRICE","CREATED_AT","UPDATED_AT","PRODUCT_CATEGORY","GENDER") VALUES
	 ('3963560b-f645-4363-bf07-87b9756b448c','Nike Zegama 2','{"title": "", "benefits": ["Ankle gaiter helps limit trail debris.", "Overlays stretch across the toe for extra durability.", "Weight: 264g approx. (Women''s UK 5.5)", "Heel-to-toe drop: 4mm", "Reflective design details", "Not intended for use as personal protective equipment (PPE)", "Colour Shown: Black/Metallic Platinum/Anthracite", "Style: FD5191-003", "Country/Region of Origin: China"], "description": "Up the mountain, through the woods, to the top of the trail you can go. Equipped with an ultra-responsive ZoomX foam midsole, the Zegama 2 is designed to conquer steep ridges, jagged rocks and races from trailhead to tip. Optimal cushioning complements a rugged outsole made for your trail running journey.", "current_price": "5,279,000₫5,279,000₫5,279,000₫", "reason_to_buy": "", "product_details": ["Weight: 264g approx. (Women''s UK 5.5)", "Heel-to-toe drop: 4mm", "Reflective design details", "Not intended for use as personal protective equipment (PPE)", "Colour Shown: Black/Metallic Platinum/Anthracite", "Style: FD5191-003", "Country/Region of Origin: China"]}','https://static.nike.com/a/images/c_limit,w_592,f_auto/t_product_v1/338c1adf-2c17-43f5-9577-b40e63f04c35/W+NIKE+ZOOMX+ZEGAMA+TRAIL+2.png',65,262.03,'2024-12-22 15:34:30.900277','2024-12-22 15:34:30.900277','running','women'),
	 ('86274d8f-0b24-4b62-b930-5d0a64cc2f8b','Nike Motiva','{"title": "", "benefits": ["Super-high cushioning", "Moderate stability", "Moderate flexibility", "Soft foam collar", "Widened forefoot, arch and toe box", "Durable outsole pattern for traction", "Colour Shown: White/Mint Foam/Sail/Sunset Tint", "Style: HQ3506-100", "Country/Region of Origin: Vietnam"], "description": "Designed for walking in ultimate comfort, the Nike Motiva provides our highest level of cushioning. A tall foam stack is combined with our Comfortgroove innovation on the outsole to absorb the bumps along the way. And its exaggerated rocker helps propel you forwards.", "current_price": "3,239,000₫3,239,000₫3,239,000₫", "reason_to_buy": "", "product_details": ["Soft foam collar", "Widened forefoot, arch and toe box", "Durable outsole pattern for traction", "Colour Shown: White/Mint Foam/Sail/Sunset Tint", "Style: HQ3506-100", "Country/Region of Origin: Vietnam"]}','https://static.nike.com/a/images/c_limit,w_592,f_auto/t_product_v1/048c038e-b99c-4c6c-867a-3b00c1821b52/WMNS+NIKE+MOTIVA.png',55,401.70,'2024-12-22 15:34:30.901302','2024-12-22 15:34:30.901302','running','women'),
	 ('df8ab743-fead-423d-811a-4eef4dafe8b4','Nike Vaporfly 3','{"title": "", "benefits": ["The light padding on the tongue helps reduce lace pressure at the top of your foot.", "The new Waffle outsole pattern with perforations saves weight and delivers multi-surface traction in various weather conditions.", "The offset heel seam helps reduce friction in the heel area.", "Wider toe area creates a roomier fit.", "An internal foam pod on the heel adds extra cushioning.", "Weight: Approx. 165 grams (women''s size 5.5)", "Heel-to-toe drop: 8mm", "Colour Shown: Mint Foam/Sunset Tint/Barely Volt/Sail", "Style: HQ3505-379", "Country/Region of Origin: China"], "description": "Catch ''em if you can. Giving you race-day speed to conquer any distance, the Nike Vaporfly 3 is for the chasers, the racers, the elevated pacers who can''t turn down the thrill of the pursuit. We reworked the leader of the super shoe pack and tuned the engine underneath to help you chase personal bests from a 10K to marathon. From elite runners to those new to racing, this versatile road-racing workhorse is for those who see speed as a gateway to more miles and more seemingly uncatchable highs.", "current_price": "7,629,000₫7,629,000₫7,629,000₫", "reason_to_buy": "", "product_details": ["Weight: Approx. 165 grams (women''s size 5.5)", "Heel-to-toe drop: 8mm", "Colour Shown: Mint Foam/Sunset Tint/Barely Volt/Sail", "Style: HQ3505-379", "Country/Region of Origin: China"]}','https://static.nike.com/a/images/c_limit,w_592,f_auto/t_product_v1/33b7edd5-bc94-4929-b897-67ce249c69ce/W+ZOOMX+VAPORFLY+NEXT%25+3FK.png',77,351.05,'2024-12-22 15:34:30.902412','2024-12-22 15:34:30.902412','running','women'),
	 ('299dfdc8-f4d2-47cf-b271-64fe023c78a7','Nike Pegasus 41 PRM','{"title": "", "benefits": ["Upgraded breathable engineered mesh upper", "ReactX foam midsole surrounds forefoot and heel Air Zoom units for an energised ride.", "Signature waffle-inspired rubber outsole for traction and flexibility", "A plush collar, tongue and sockliner for a secure and comfortable fit", "What''s new? All-new ReactX foam midsole is 13% more responsive than previous React technology.", "Crafted for performance and planet, ReactX foam is engineered to reduce its carbon footprint by at least 43% in a pair of midsoles due to reduced manufacturing process energy compared with prior React foam. The carbon footprint of ReactX is based on cradle-to-gate assessment reviewed by PRé Sustainability B.V. and Intertek China. Other midsole components such as airbags, plates or other foam formulations were not considered.", "Reflective design Swoosh logo, overlays and laces", "Not intended for use as personal protective equipment (PPE)", "Weight: Approx. 251g (women''s size 5.5)", "Heel-to-toe drop: 10mm", "MR-10 last—our best, most consistent fit (same as Pegasus 40)", "Colour Shown: Hot Fuchsia/Light Silver/Medium Fuchsia/Metallic Silver", "Style: FZ1626-500", "Country/Region of Origin: China"], "description": "Responsive cushioning in the winterized Pegasus provides an energised ride for everyday road running, day or night. Experience lighter-weight energy return with dual Air Zoom units and a ReactX foam midsole. Plus, reflective design paint on the upper lights up your route.", "current_price": "4,109,000₫4,109,000₫4,109,000₫", "reason_to_buy": "", "product_details": ["Upgraded breathable engineered mesh upper", "ReactX foam midsole surrounds forefoot and heel Air Zoom units for an energised ride.", "Signature waffle-inspired rubber outsole for traction and flexibility", "A plush collar, tongue and sockliner for a secure and comfortable fit", "What''s new? All-new ReactX foam midsole is 13% more responsive than previous React technology.", "Crafted for performance and planet, ReactX foam is engineered to reduce its carbon footprint by at least 43% in a pair of midsoles due to reduced manufacturing process energy compared with prior React foam. The carbon footprint of ReactX is based on cradle-to-gate assessment reviewed by PRé Sustainability B.V. and Intertek China. Other midsole components such as airbags, plates or other foam formulations were not considered.", "Reflective design Swoosh logo, overlays and laces", "Not intended for use as personal protective equipment (PPE)", "Weight: Approx. 251g (women''s size 5.5)", "Heel-to-toe drop: 10mm", "MR-10 last—our best, most consistent fit (same as Pegasus 40)", "Colour Shown: Hot Fuchsia/Light Silver/Medium Fuchsia/Metallic Silver", "Style: FZ1626-500", "Country/Region of Origin: China"]}','https://static.nike.com/a/images/c_limit,w_592,f_auto/t_product_v1/75ab75dc-03db-4e4b-8893-e804ee9e895c/W+AIR+ZOOM+PEGASUS+41+PRM.png',68,316.00,'2024-12-22 15:34:30.903376','2024-12-22 15:34:30.903376','running','women'),
